window.JBC_LEVEL_B_87=[{"candidate_id":"ATLBC-CAND-0001","name_en":"Ai","name_ko":"아이","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-AI","ko":"일체 포함. 아이 폐허. (1) 가나안 사람들의 왕도 중 하나(수 10:1; 창 12:8; 13:3). 여호수아가 패한 장면과 그 후에 승리한 장면이었습니다. 이곳은 이스라엘이 두 번째로 점령한 가나안 도시였습니다(수 7:2-5; 8:1-29). 그것은 베냐민 사람들에 의해 재건되고 금지되었습니다(스 2:28; 느 7:32; 11:31). 그곳은 벧엘 동쪽, “벧아웬 옆”에 있었습니다. 이 고대 도시의 유적지일 가능성이 가장 높은 곳은 베델에서 동쪽으로 3.2km 떨어진 하이옌(Haiyan)입니다. 그것은 요르단 계곡에서 베델까지 뻗어 있는 가파르고 험준한 계곡인 와디 수웨이닛(Wady Suweinit)을 형성합니다. (2) 암몬 영토에 있는 도시(렘 49:3). 어떤 사람들은 이 단어를 아르(Ar)로 읽는 것이 적절하다고 생각합니다(사 15:1).","source_sha256":"46c51f5c5db742622294fdac4f565cc9c519defb7339b9a6288cf0aa8663a00f","citation_candidates":[{"source":"Josh. 10:1","passage":"jos-10","verse":1,"ref":"jos-10:1","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Gen. 12:8","passage":"gen-12","verse":8,"ref":"gen-12:8","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Josh. 7:2-5","passage":"jos-7","verse":2,"ref":"jos-7:2","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Ezra 2:28","passage":"ezr-2","verse":28,"ref":"ezr-2:28","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Neh. 7:32","passage":"neh-7","verse":32,"ref":"neh-7:32","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Jer. 49:3","passage":"jer-49","verse":3,"ref":"jer-49:3","status":"KRV_VERIFIED","exact_korean_token":"아이"},{"source":"Isa. 15:1","passage":"isa-15","verse":1,"ref":"isa-15:1","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0002","name_en":"Anathoth","name_ko":"아나돗","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ANATHOTH","ko":"아나돗. 아나돗 베냐민 지파의 도피성 중 하나의 이름(수 21:18). 유대인들은 원칙적으로 팔레스타인에서 발견한 마을의 이름을 바꾸지 않았습니다. 따라서 이 도시는 그 이름이 아나트 여신에게서 유래한 것으로 간주될 수 있습니다. 이곳은 다윗의 “삼십인” 중 하나인 아비에셀(삼하 23:27)과 그의 또 다른 용사인 예후(대상 12:3)의 출신지였다. 그러나 이곳은 예레미야가 태어난 곳이자 평소 거주했던 곳으로 특히 주목할 만하다(렘 1:1; 11:21-23; 29:27; 32:7-9). 산헤립의 군대로 인해 큰 피해를 입었고 포로 생활에서 돌아온 사람은 128명에 불과했습니다(느 7:27; 스 2:23). 그곳은 예루살렘에서 북쪽으로 약 3마일 떨어진 곳에 위치해 있었습니다. 주민 100여명이 살고 있는 작고 가난한 마을 '아나타'로 확인됐다.","source_sha256":"6f9d09da39a4d3b8017aecb5ecc22d57d0f8e2bfb990103d068f1e53dec8093b","citation_candidates":[{"source":"Josh. 21:18","passage":"jos-21","verse":18,"ref":"jos-21:18","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"2 Sam. 23:27","passage":"2sa-23","verse":27,"ref":"2sa-23:27","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"1 Chr. 12:3","passage":"1ch-12","verse":3,"ref":"1ch-12:3","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"Jer. 1:1","passage":"jer-1","verse":1,"ref":"jer-1:1","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"Neh. 7:27","passage":"neh-7","verse":27,"ref":"neh-7:27","status":"KRV_VERIFIED","exact_korean_token":"아나돗"},{"source":"Ezra 2:23","passage":"ezr-2","verse":23,"ref":"ezr-2:23","status":"KRV_VERIFIED","exact_korean_token":"아나돗"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0003","name_en":"Antioch","name_ko":"안디옥","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ANTIOCH","ko":"안디옥. 안디옥 (1.) 시리아의 오론테스 강가에 있는 곳으로 지중해에서 약 16마일, 예루살렘에서 북쪽으로 약 300마일 떨어져 있습니다. 이곳은 시리아의 대도시였으며 나중에는 아시아 로마 지방의 수도가 되었습니다. 로마제국의 도시들 중 중요도 측면에서 로마와 알렉산드리아에 이어 세 번째로 꼽혔다. 그곳은 “동방의 첫 번째 도시”라고 불렸습니다. 기독교가 일찍부터 소개되었고(행 11:19, 21, 24), “기독교인”이라는 이름은 여기서 처음으로 그 교수들에게 적용되었습니다(행 11:26). 이는 복음의 초기 역사와 밀접하게 연결되어 있다(행 6:5; 11:19, 27, 28, 30; 12:25; 15:22-35; 갈 2:11, 12). 이곳은 이방인 선교사들이 파견되는 가장 중요한 지점이었습니다. 이곳은 서기 407년에 사망한 유명한 기독교 교부 크리소스톰(Chrysostom)의 출생지였습니다. 안타키아는 지금은 비참하고 부패해가는 터키 마을이 되었습니다. 빌립보와 마찬가지로 로마 식민지 수준까지 올라갔습니다. 그러한 식민지는 “집정관”(R.V. marg., 행 16:20, 21)에 의해 통치되었습니다. (2.) 피시디아의 북쪽 끝. 1차 전도여행 때 바울과 바나바의 방문을 받았다(행 13:14). 여기서 그들은 회당과 많은 개종자들을 발견했습니다. 그들이 복음을 전하여 큰 성공을 거두었으나 유대인들이 그들을 대적하여 폭력을 행사하여 부득이 그 곳을 떠나게 되었느니라. 바울은 돌아오는 길에 제자들을 확증하기 위해 다시 안디옥을 방문했습니다(행 14:21). 그것은 에베소 동쪽에 있는 현대의 얄로바치(Yalobatch)와 동일시된다.","source_sha256":"cf0b1bf85acfd0ca95267bb49d0a79cb76d21543a0b313278b684a56efc19422","citation_candidates":[{"source":"Acts 11:19","passage":"act-11","verse":19,"ref":"act-11:19","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Acts 11:26","passage":"act-11","verse":26,"ref":"act-11:26","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Acts 6:5","passage":"act-6","verse":5,"ref":"act-6:5","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Gal. 2:11","passage":"gal-2","verse":11,"ref":"gal-2:11","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Acts 16:20","passage":"act-16","verse":20,"ref":"act-16:20","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Acts 13:14","passage":"act-13","verse":14,"ref":"act-13:14","status":"KRV_VERIFIED","exact_korean_token":"안디옥"},{"source":"Acts 14:21","passage":"act-14","verse":21,"ref":"act-14:21","status":"KRV_VERIFIED","exact_korean_token":"안디옥"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0004","name_en":"Antipatris","name_ko":"안디바드리","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ANTIPATRIS","ko":"안티파트리스. 안티파트리스 헤롯 대왕이 건설한 도시로, 그의 아버지 안티파트로스를 기리기 위해 이 이름으로 불렸다. 그곳은 가이사랴에서 예루살렘까지 로마의 큰 도로에 있는 내륙으로 2마일 떨어진 가이사랴와 룻다 사이에 있었습니다. 바울은 가이사랴로 가던 중 밤에 이곳으로 끌려갔는데(행 23:31) 그곳에서 40킬로미터나 떨어져 있었습니다. 이곳은 팔레스타인에서 가장 큰 샘인 아우제(Aujeh) 샘이 솟아오르는 현대의 라스엘아인(Ras-el-Ain)과 동일시됩니다.","source_sha256":"0288475433d491d62ad0c23cb4e22de0de570c3d170f6d9b9308bb05cfec8f17","citation_candidates":[{"source":"Acts 23:31","passage":"act-23","verse":31,"ref":"act-23:31","status":"KRV_VERIFIED","exact_korean_token":"안디바드리"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0005","name_en":"Arad","name_ko":"아랏","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ARAD","ko":"아라드. 아랏 (1.) 이제 헤브론에서 남쪽으로 약 20 마일 떨어진 가나안 도시인 아랏에게 말하십시오. 아랏 왕은 이스라엘이 에돔 국경에서 후퇴하고 있을 때 “이스라엘과 싸워 그들을 포로로 잡았습니다”(민 21:1; 33:40; 삿 1:16). 마침내 여호수아에 의해 정복되었습니다(12:14). (2) 브리아의 아들 중 한 사람(대상 8:15).","source_sha256":"7da653ae29611c100f13b4ff6ead44bbe0a0cc7fcc99b6a7ae6763c6e369521f","citation_candidates":[{"source":"Num. 21:1","passage":"num-21","verse":1,"ref":"num-21:1","status":"KRV_VERIFIED","exact_korean_token":"아랏"},{"source":"Judg. 1:16","passage":"jdg-1","verse":16,"ref":"jdg-1:16","status":"KRV_VERIFIED","exact_korean_token":"아랏"},{"source":"1 Chr. 8:15","passage":"1ch-8","verse":15,"ref":"1ch-8:15","status":"KRV_VERIFIED","exact_korean_token":"아랏"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0006","name_en":"Arimathea","name_ko":"아리마대","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ARIMATHEA","ko":"아리마대. 아리마대 “유대인의 동네”(누가복음 23:51), 요셉이 태어난 곳으로 우리 주님의 무덤이 그 곳에 있습니다(마 27:57, 60; 요한복음 19:38). 아마도 에브라임의 라마다임과 사무엘의 출생지(삼상 1:1, 19)와 같은 곳일 것이다. 다른 사람들은 그것을 단(Dan)의 람레(Ramleh)나 베냐민(Benjamin)의 라마(Rama)(마태복음 2:18)와 동일시합니다.","source_sha256":"4fbc073852dffc5b58c0cbc119530a748b26d955ff1292f7f591bb00cf84f722","citation_candidates":[{"source":"Luke 23:51","passage":"luk-23","verse":51,"ref":"luk-23:51","status":"KRV_VERIFIED","exact_korean_token":"아리마대"},{"source":"Matt. 27:57","passage":"mat-27","verse":57,"ref":"mat-27:57","status":"KRV_VERIFIED","exact_korean_token":"아리마대"},{"source":"John 19:38","passage":"jhn-19","verse":38,"ref":"jhn-19:38","status":"KRV_VERIFIED","exact_korean_token":"아리마대"},{"source":"1 Sam. 1:1","passage":"1sa-1","verse":1,"ref":"1sa-1:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Matt. 2:18","passage":"mat-2","verse":18,"ref":"mat-2:18","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0008","name_en":"Ashkelon","name_ko":"아스글론","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ASHKELON","ko":"아스글론. 아스글론 = 아스글론 = 아스갈론은 블레셋의 다섯 성읍 중 하나였습니다(수 13:3; 삼상 6:17). 그것은 가자에서 북쪽으로 12마일 떨어진 지중해 해안에 서 있었습니다. 이집트의 카르나크에 있는 비문에는 히브리인을 압제했던 왕 라메세스 2세가 빼앗은 것으로 언급되어 있습니다. 사사 시대(삿 1:18)에는 유다 지파의 소유가 되었고, 그러나 곧 블레셋 사람들이 그곳을 되찾았으며(삼하 1:20), 그들은 알렉산더 대왕 시대까지 최종적으로 빼앗기지 않았다. 삼손은 딤나에서 이곳으로 내려와서 삼십 명을 죽이고 그들의 약탈을 하였느니라. 선지자들은 그 도시의 멸망을 예언했습니다(렘 25:20; 47:5, 7). 이곳은 사라센족과 십자군 사이에 수많은 피비린내 나는 전투가 벌어졌던 중세 시대의 유명한 장소가 되었습니다. Richard가 포위하여 점령했습니다. 사자 같은 마음을 갖고 “그는 지금 서 있는 성벽과 탑 안에 궁정을 열었습니다.” 텔 아마르나 서판(이집트 참조) 중에는 “말의 대장이자 왕의 발의 티끌”인 야다야가 이집트의 “대왕”에게 보낸 편지나 공식 서신이 아스칼론에서 발견됩니다. 지금은 '아스칼란'이라고 불린다.","source_sha256":"b89946c311bdf6d67038f3ba012be2c94aa58bd3b6f8f8c1c40a40ad9affb53f","citation_candidates":[{"source":"Josh. 13:3","passage":"jos-13","verse":3,"ref":"jos-13:3","status":"KRV_VERIFIED","exact_korean_token":"아스글론"},{"source":"1 Sam. 6:17","passage":"1sa-6","verse":17,"ref":"1sa-6:17","status":"KRV_VERIFIED","exact_korean_token":"아스글론"},{"source":"Judg. 1:18","passage":"jdg-1","verse":18,"ref":"jdg-1:18","status":"KRV_VERIFIED","exact_korean_token":"아스글론"},{"source":"2 Sam. 1:20","passage":"2sa-1","verse":20,"ref":"2sa-1:20","status":"KRV_VERIFIED","exact_korean_token":"아스글론"},{"source":"Jer. 25:20","passage":"jer-25","verse":20,"ref":"jer-25:20","status":"KRV_VERIFIED","exact_korean_token":"아스글론"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0009","name_en":"Athens","name_ko":"아덴","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ATHENS","ko":"아테네. 아테네 고대 세계에서 가장 유명한 도시인 아티카의 수도이자 그리스 역사의 황금기 동안 그리스 문학과 예술의 중심지였습니다. 그 주민들은 새로운 것을 좋아했고(행 17:21), 신을 숭배하는 데 있어서 그들의 열심은 주목할 만했습니다. “아테네에서는 사람을 찾는 것보다 신을 찾는 것이 더 쉽다”는 로마 풍자가의 비꼬는 말이었다. 바울은 그의 두 번째 선교 여행 중에 이 도시를 방문했고(행 17:15; 살전 3:1을 비교하라) 아레오바고에서 그의 유명한 연설을 했다(17:22-31). 바울이 거기서 “알지 못하는 신에게”(23) 바쳐졌다고 말한 제단은 아마도 같은 문구가 새겨진 여러 제단 중 하나였을 것입니다. 전염병이 돌았을 때 아테네의 거리에 양과 염소 떼를 풀어놓는 관습에서 유래했다고 추정됩니다. 그들이 누워 있던 곳에서 “해당 신에게” 희생 제물로 바쳐졌습니다.","source_sha256":"d2f2834d7b2cac1ef33db1d6a0dc62c1182d015061c599e1c043864f64cc5d75","citation_candidates":[{"source":"Acts 17:21","passage":"act-17","verse":21,"ref":"act-17:21","status":"KRV_VERIFIED","exact_korean_token":"아덴"},{"source":"Acts 17:15","passage":"act-17","verse":15,"ref":"act-17:15","status":"KRV_VERIFIED","exact_korean_token":"아덴"},{"source":"1 Thess. 3:1","passage":"1th-3","verse":1,"ref":"1th-3:1","status":"KRV_VERIFIED","exact_korean_token":"아덴"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0011","name_en":"Bethany","name_ko":"베다니","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETHANY","ko":"베다니. 베다니 하우스 오브 데이트. (1.) 요한복음 1장 28절의 개정판은 가장 오래된 사본의 권위에 따라 베다바라 대신에 이 단어를 사용합니다. 그것은 요르단 동쪽에 있는 한 장소의 이름이었던 것으로 보인다. (2) 예루살렘에서 동쪽으로 약 3.2km 떨어진 여리고로 가는 길목에 있는 감람산 남동쪽 경사면에 있는 마을(막 11:1). 그곳에서 자라는 야자수의 수에서 그 이름이 유래되었습니다. 그곳은 나사로와 그의 자매들의 거주지였습니다. 그것은 우리 주님의 생애에서 기억에 남는 사건과 관련하여 자주 언급됩니다(마 21:17; 26:6; 막 11:11, 12; 14:3; 눅 24:50; 요한복음 11:1; 12:1). 현재 이곳은 엘-아자리예(el-Azariyeh), 즉 “나사로의 장소” 또는 단순히 라자리예(Lazariyeh)라는 이름으로 알려져 있습니다. 멀리서 보면 마을은 “매우 아름답고, 은퇴와 휴식의 완벽함, 은둔과 사랑스러운 평화.” 지금은 약 20가구가 살고 있는 비열한 마을입니다.","source_sha256":"d1ec401fd13e8530ccb1807dc5d5983a020f450e67c69c5fec14bf31b86139b4","citation_candidates":[{"source":"John 1:28","passage":"jhn-1","verse":28,"ref":"jhn-1:28","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"Mark 11:1","passage":"mrk-11","verse":1,"ref":"mrk-11:1","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"Matt. 21:17","passage":"mat-21","verse":17,"ref":"mat-21:17","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"Mark 11:11","passage":"mrk-11","verse":11,"ref":"mrk-11:11","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"Luke 24:50","passage":"luk-24","verse":50,"ref":"luk-24:50","status":"KRV_VERIFIED","exact_korean_token":"베다니"},{"source":"John 11:1","passage":"jhn-11","verse":1,"ref":"jhn-11:1","status":"KRV_VERIFIED","exact_korean_token":"베다니"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0012","name_en":"Bethsaida","name_ko":"벳새다","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETHSAIDA","ko":"벳새다. 벳새다 물고기의 집. (1) 디베랴 바다 서쪽, “게네사렛 땅”에 있는 갈릴리에 있는 한 마을. 이곳은 베드로, 안드레, 빌립의 고향이었으며 예수께서 자주 찾으셨던 곳이었습니다(막 6:45; 요한복음 1:44; 12:21). 그것은 게네사렛 북쪽에 있는 만인 현대의 '아인 타비가(Ain Tabighah)'에 있었던 것으로 추정됩니다. (2.) 그리스도께서 5,000명을 먹이셨던 근처의 도시(눅 9:10; 요한 6:17; 마 14:15-21을 비교하라)와 소경이 시력을 회복한 곳(막 8:22)은 요단 강에서 2마일 떨어진 호수 동쪽에 있는 도시이다. 그것은 Gaulonitis 지역에 있었고, 황제의 딸의 이름을 따서 \"Julias\"라고 불렀던 분봉왕 필리포스에 의해 확장되었습니다. 또는 일부 사람들이 생각하는 것처럼, 요르단 강이 호수로 들어가는 곳 근처의 호수 양쪽에 벳새다는 하나만 세워졌을 수도 있습니다. 이제 폐허 et-Tel.","source_sha256":"e88fdc913b57f1e48edc3975e90d36dd6fb5514308eb06533c21d16455477424","citation_candidates":[{"source":"Mark 6:45","passage":"mrk-6","verse":45,"ref":"mrk-6:45","status":"KRV_VERIFIED","exact_korean_token":"벳새다"},{"source":"John 1:44","passage":"jhn-1","verse":44,"ref":"jhn-1:44","status":"KRV_VERIFIED","exact_korean_token":"벳새다"},{"source":"Luke 9:10","passage":"luk-9","verse":10,"ref":"luk-9:10","status":"KRV_VERIFIED","exact_korean_token":"벳새다"},{"source":"John 6:17","passage":"jhn-6","verse":17,"ref":"jhn-6:17","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Matt. 14:15-21","passage":"mat-14","verse":15,"ref":"mat-14:15","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Mark 8:22","passage":"mrk-8","verse":22,"ref":"mrk-8:22","status":"KRV_VERIFIED","exact_korean_token":"벳새다"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0013","name_en":"Beth-horon","name_ko":"벧호론","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETH-HORON","ko":"벳호론. 벳호론 벳호론 예루살렘에서 욥바로 가는 길에 있는 에브라임 영토에 있는 두 성읍이나 마을의 이름인 굴 또는 굴의 집. 그들은 벳호론(위쪽)과 벳호론(아래쪽)으로 구분됩니다. 두 곳은 약 2마일 떨어져 있으며 전자는 예루살렘에서 북서쪽으로 약 10마일 떨어져 있습니다. 두 곳 사이에는 기브온에서 서쪽 평야까지 이어지는 벳호론의 오르막과 내리막이 있었다(수 10:10, 11; 18:13, 14). 그곳에서 아모리 사람의 다섯 왕은 그 큰 전투에서 여호수아에 의해 쫓겨났다. 이 전투는 히브리인들이 지금까지 싸웠던 가장 중요한 전투로서 들판에서 적들과 처음으로 싸우는 전투였다. 여호와께서는 이스라엘을 위해 무서운 우박을 내리시어 개입하셨습니다. 그로 인해 가나안 사람들 가운데는 가나안 사람들의 칼에 죽은 사람보다 더 많은 사람이 죽게 되었습니다. 이스라엘 사람들. 벳호론은 B.C. 시삭이 점령한 것으로 언급되어 있다. 945년에 그의 정복 목록에 기록되어 있으며, 그 고개는 유다 마카베우스의 승리 장면이었습니다. (출 9:19, 25; 욥 38:22, 23; 시 18:12-14; 이사야 30:30 비교) 이 장소들의 현대적 이름은 베이트우르인데, “위쪽”을 의미하는 엘포카와 “아래쪽”을 의미하는 엘타타로 구별됩니다. 아래쪽은 고개 기슭에 있었고 위쪽은 기브온 서쪽 꼭대기에 500피트 더 높았습니다. (기브온 참조)","source_sha256":"71407f804e5b4395ff962039d93f712fd1dfaa0e3aff37b9f7afb0264415e675","citation_candidates":[{"source":"2 Chr. 8:5","passage":"2ch-8","verse":5,"ref":"2ch-8:5","status":"KRV_VERIFIED","exact_korean_token":"벧호론"},{"source":"1 Chr. 7:24","passage":"1ch-7","verse":24,"ref":"1ch-7:24","status":"KRV_VERIFIED","exact_korean_token":"벧호론"},{"source":"Josh. 10:10","passage":"jos-10","verse":10,"ref":"jos-10:10","status":"KRV_VERIFIED","exact_korean_token":"벧호론"},{"source":"Job 38:22","passage":"job-38","verse":22,"ref":"job-38:22","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Ps. 18:12-14","passage":"psa-18","verse":12,"ref":"psa-18:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Isa. 30:30","passage":"isa-30","verse":30,"ref":"isa-30:30","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0014","name_en":"Beth-shean","name_ko":"벧스안","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETH-SHEAN","ko":"벳스안. 벳스안 안식의 집. 요단 서쪽 므낫세에 속한 도시(대상 7:29). 사울과 그의 아들들의 시체가 성벽에 고정되어 있었습니다. 솔로몬 시대에는 그 지역의 이름을 따왔습니다(왕상 4:12). 그 이름은 삼상에서 벳산(Bethshan)이라는 축약형으로 나타난다. 31:10, 12, 삼하 21:12. 예루살렘에서 다메섹으로 가는 길에 있으며, 요단강에서 약 5마일, 게네사렛 호수 남쪽 끝에서 14마일 떨어져 있습니다. 포로 생활 이후에는 스키토폴리스, 즉 \"스키타이인의 도시\"라고 불렸습니다. 640명은 러시아 남부의 대초원에서 내려와 시리아의 여러 곳에 정착했습니다. 지금은 베이산(Beisan)이라고 불린다.","source_sha256":"688c2f9f6880c458ae252b55b450fe3ad63c1eafacdea23b76eb5791870f4ece","citation_candidates":[{"source":"1 Chr. 7:29","passage":"1ch-7","verse":29,"ref":"1ch-7:29","status":"KRV_VERIFIED","exact_korean_token":"벧스안"},{"source":"1 Kings 4:12","passage":"1ki-4","verse":12,"ref":"1ki-4:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 31:10","passage":"1sa-31","verse":10,"ref":"1sa-31:10","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Sam. 21:12","passage":"2sa-21","verse":12,"ref":"2sa-21:12","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0015","name_en":"Beth-shemesh","name_ko":"벧세메스","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETH-SHEMESH","ko":"벳세메스. 벳세메스 태양의 집. (1) 유다 북쪽 경계에 있는(수 15:10) 단 지파의 성직자 도시(수 21:16; 삼상 6:15). 이스라엘 왕 요아스와 유다 왕 아마샤가 만나 포로가 된 장면이었습니다(왕하 14:11, 13). 그 후에 블레셋 사람들이 그곳을 점령하였다(대하 28:18). 이곳은 예루살렘에서 서쪽으로 14마일 떨어진 유다 산맥의 북서쪽 경사면에 위치한 현대의 폐허가 된 아랍 마을인 '아인 셈스'입니다. (2) 잇사갈의 남쪽 경계 근처에 있는 도단과 요단강 사이의 도시(수 19:22), 벳스안에서 남쪽으로 7.5마일 떨어져 있다. 현대의 Ain-esh-Shemsiyeh입니다. (3) 다볼산과 요단강 사이에 있는 납달리의 울타리 있는 도시 중 하나(수 19:38). 이제 Safed에서 서쪽으로 3마일 떨어진 Khurbet Shema에 있습니다. 하지만 아마도 2번과 같을 것이다. (4.) 아이돌 애굽의 성소(렘 43:13); 그리스인 헬리오폴리스(Heliopolis)와 이집트인(On)(q.v.)에 의해 부름됨, 창 41:45.","source_sha256":"c427e0be2bdc4088d6d791f0c739bacdbbee2d47d02b174428a228086caa4572","citation_candidates":[{"source":"Josh. 21:16","passage":"jos-21","verse":16,"ref":"jos-21:16","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 6:15","passage":"1sa-6","verse":15,"ref":"1sa-6:15","status":"KRV_VERIFIED","exact_korean_token":"벧세메스"},{"source":"Josh. 15:10","passage":"jos-15","verse":10,"ref":"jos-15:10","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 14:11","passage":"2ki-14","verse":11,"ref":"2ki-14:11","status":"KRV_VERIFIED","exact_korean_token":"벧세메스"},{"source":"2 Chr. 28:18","passage":"2ch-28","verse":18,"ref":"2ch-28:18","status":"KRV_VERIFIED","exact_korean_token":"벧세메스"},{"source":"Josh. 19:22","passage":"jos-19","verse":22,"ref":"jos-19:22","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Josh. 19:38","passage":"jos-19","verse":38,"ref":"jos-19:38","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Jer. 43:13","passage":"jer-43","verse":13,"ref":"jer-43:13","status":"KRV_VERIFIED","exact_korean_token":"벧세메스"},{"source":"Gen. 41:45","passage":"gen-41","verse":45,"ref":"gen-41:45","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0017","name_en":"Bozrah","name_ko":"보스라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BOZRAH","ko":"보스라. 보스라 인클로저; 요새. (1) 초기 에돔 왕 중 하나인 요밥의 도시(창 36:33). 이 장소는 후대의 선지자들에 의해 언급되었습니다(사 34:6; 렘 49:13; 암 1:12; 미 2:12). 현대 대표자는 el-Busseireh입니다. 사해에서 남동쪽으로 20마일 떨어진 페트라(Petra) 산악 지역에 위치해 있습니다. (2.) “평지”(렘 48:24), 즉 사해 동쪽 높은 곳에 있는 모압의 도시. 아마도 현대의 부즈라(Buzrah)일 것이다.","source_sha256":"0e971decbbc8b07553a662eef743d4f597acae0670c58aad45261a39537efcbb","citation_candidates":[{"source":"Gen. 36:33","passage":"gen-36","verse":33,"ref":"gen-36:33","status":"KRV_VERIFIED","exact_korean_token":"보스라"},{"source":"Isa. 34:6","passage":"isa-34","verse":6,"ref":"isa-34:6","status":"KRV_VERIFIED","exact_korean_token":"보스라"},{"source":"Jer. 49:13","passage":"jer-49","verse":13,"ref":"jer-49:13","status":"KRV_VERIFIED","exact_korean_token":"보스라"},{"source":"Amos 1:12","passage":"amo-1","verse":12,"ref":"amo-1:12","status":"KRV_VERIFIED","exact_korean_token":"보스라"},{"source":"Micah 2:12","status":"UNSUPPORTED_BOOK"},{"source":"Jer. 48:24","passage":"jer-48","verse":24,"ref":"jer-48:24","status":"KRV_VERIFIED","exact_korean_token":"보스라"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0018","name_en":"Caesarea","name_ko":"가이사랴","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CAESAREA","ko":"가이사랴. 가이사랴(팔레스타인)는 예루살렘에서 북서쪽으로 약 70마일 떨어진 샤론 평야의 북단에 있는 두로에서 이집트로 가는 큰 길에 있는 지중해 연안에 있는 도시입니다. 그것은 헤롯 대왕(B.C. 10)에 의해 건설되었으며, 그는 카이사르 아우구스투스의 이름을 따서 이 도시를 가이사랴 세바스테(Gr. Sebastos = “Augustus”)라고 불렀으며, “스트라토의 탑”이라고 불리는 구시가지 부지에 건설했습니다. 이곳은 로마 유대 지방의 수도이자 총독이나 총독의 소재지이자 로마 군대의 본부였습니다. 그곳은 넓은 인공 항구가 있는 거대한 이방인 도시 팔레스타인이었습니다. 그곳은 서로마의 로마 도시의 방식을 따라 매우 화려하고 많은 건물들로 장식되었습니다. 여기서 백부장 고넬료는 베드로를 통해 회심하였고(행 10:1, 24) 믿음이 이방인들에게 열렸느니라. 전도자 빌립이 네 딸과 함께 이곳에 거주했습니다(21:8). 사울은 예루살렘에서 강제로 도망할 때 이곳에서 배를 타고 고향 다소로 왔고(9:30), 2차 선교 여행을 마치고 돌아올 때 여기에 상륙했습니다(18:22). 그는 로마로 항해하기 전까지 이곳에서 2년 동안 죄수로 지냈습니다(행 24:27; 25:1, 4, 6, 13). 여기 “정해진 날”에 극장에서 클라우디우스 황제를 기리는 경기가 거행되었을 때, 헤롯 아그리파 1세는 화려하게 사람들 가운데 나타났고, 그에게 우상 숭배를 드리는 가운데 갑자기 천사에게 치여 죽어가는 사람을 처형했습니다. 그는 “벌레에게 먹혀”(12:19-23) 그의 할아버지인 헤롯 대왕과 똑같은 역겨운 질병으로 죽었습니다. 이곳은 여전히 ​​고대 이름인 Kaiseriyeh를 유지하고 있지만 지금은 황폐해졌습니다. “현재 폐허의 주민은 뱀, 전갈, 도마뱀, 멧돼지, 자칼입니다.” 팔레스타인 전체에서 가장 황량한 도시로 묘사된다.","source_sha256":"e35b81d4b7ba555ece4556031587c489cbb86a6bf1f8c4f1f67628ff9f376842","citation_candidates":[{"source":"Acts 10:1","passage":"act-10","verse":1,"ref":"act-10:1","status":"KRV_VERIFIED","exact_korean_token":"가이사랴"},{"source":"Acts 24:27","passage":"act-24","verse":27,"ref":"act-24:27","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0019","name_en":"Capernaum","name_ko":"가버나움","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CAPERNAUM","ko":"가버나움. 가버나움 나훔의 동네는 우리 주님의 역사에 자주 언급되는 갈릴리 도시입니다. 구약성서에는 언급되어 있지 않습니다. 우리 주님이 나사렛에서 쫓겨나신 후(마태복음 4:13-16; 누가복음 4:16-31), 가버나움은 그분의 “고성”이 되었습니다. 그곳은 그의 생애에서 많은 사건과 사건이 일어난 곳이었습니다(마 8:5, 14, 15; 9:2-6, 10-17; 15:1-20; 막 1:32-34 등). 우리 주님께서 그분의 사명이 진실하다는 많은 증거를 그들에게 주신 후에도 그 주민들의 회개하지 않음과 불신은 그들에게 엄중한 심판의 선고를 내리게 했습니다(마 11:23). 그 곳은 갈릴리 바다 서쪽 해안에 있었습니다. “게네사렛 땅”은 그 땅이 있던 곳은 아니더라도 그 근처에 있었는데, 팔레스타인에서 가장 번영하고 인구가 많은 지역 중 하나였습니다. 이 도시는 다메섹에서 아고와 두로로 이어지는 큰 대로에 위치해 있었습니다. 이는 다음과 같은 것으로 확인되었습니다. 요르단 강이 호수로 흘러드는 곳에서 남서쪽으로 약 2마일 떨어진 곳인 훔(Tell Hum)에 있습니다. 여기에는 벽과 기초의 광대한 폐허와 아름다운 회당이었던 것으로 추정되는 유적이 있습니다. 이 회당은 우리 주님이 자주 가르치셨던(요한복음 6:59; 마가복음 1:21; 누가복음 4:33) 백부장이 지은 회당이었을 것으로 추측됩니다(누가복음 7:5). 다른 사람들은 도시의 폐허가 남쪽으로 약 3마일 더 떨어진 호수 기슭의 칸 미녜(Khan Minyeh)에서 발견될 것이라고 추측했습니다. \"만약 텔훔이 가버나움이라면, 언급된 유적은 의심할 바 없이 로마 백부장이 지은 회당의 폐허이자 지상에서 가장 신성한 장소 중 하나이다. 우리 주님께서 요한복음 6장에서 잘 알려진 설교를 하신 곳이 바로 이 건물이었다. 큰 블록을 뒤집어서 우리가 솥을 발견했을 때 이상한 느낌이 없지 않았다. 만나를 그 얼굴에 새겼으니 이는 내가 곧 생명의 떡이니 너희 조상들은 광야에서 만나를 먹고도 죽었느니라 하신 말씀을 기억한 것이니라.”(예루살렘의 회복)","source_sha256":"08839ee4eec48cc2c0f922998d38d6a3641aa2d9efff55ba62cb1e72f4ba332f","citation_candidates":[{"source":"Matt. 4:13-16","passage":"mat-4","verse":13,"ref":"mat-4:13","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Luke 4:16-31","passage":"luk-4","verse":16,"ref":"luk-4:16","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Matt. 8:5","passage":"mat-8","verse":5,"ref":"mat-8:5","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Mark 1:32-34","passage":"mrk-1","verse":32,"ref":"mrk-1:32","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Matt. 11:23","passage":"mat-11","verse":23,"ref":"mat-11:23","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Luke 7:5","passage":"luk-7","verse":5,"ref":"luk-7:5","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"John 6:59","passage":"jhn-6","verse":59,"ref":"jhn-6:59","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Mark 1:21","passage":"mrk-1","verse":21,"ref":"mrk-1:21","status":"KRV_VERIFIED","exact_korean_token":"가버나움"},{"source":"Luke 4:33","passage":"luk-4","verse":33,"ref":"luk-4:33","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0021","name_en":"Carchemish","name_ko":"갈그미스","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CARCHEMISH","ko":"카르케미스. 유프라테스 서안의 도시인 그모스의 갈그미스 요새(렘 46:2; 대하 35:20). 한때 추측되었던 것처럼 그발과 유프라테스의 합류 지점에 있는 키르케시움이 아니라 강보다 훨씬 더 높은 곳에 있는 도시이며 유프라테스의 일반적인 통행을 지휘하는 도시이다. 아마도 히에라폴리스와 동일할 것입니다. 북부 히타이트 왕국의 수도였습니다. 나보폴라살의 아들 느부갓네살 휘하의 바빌로니아 군대는 이곳에서 이집트 왕 바로느고의 군대를 만나 승리했습니다(B.C. 607). 이는 B.C.의 기념물에 언급되어 있습니다. 1600년부터 기원전까지 717.","source_sha256":"d8898f60dbb6c8da37ac61b9e6b045c80f585ed93cf8fb0074e52fe67b958b73","citation_candidates":[{"source":"Jer. 46:2","passage":"jer-46","verse":2,"ref":"jer-46:2","status":"KRV_VERIFIED","exact_korean_token":"갈그미스"},{"source":"2 Chr. 35:20","passage":"2ch-35","verse":20,"ref":"2ch-35:20","status":"KRV_VERIFIED","exact_korean_token":"갈그미스"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0022","name_en":"Chorazin","name_ko":"고라신","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CHORAZIN","ko":"코라진. 고라신은 벳새다, 가버나움과 함께 우리 주님의 “큰 일”이 행해진 도시 중 하나로 언급되었으며, 그 도시는 현저한 특권이 무시되었기 때문에 비탄에 빠질 운명에 처해 있었습니다(마 11:21; 눅 10:13). 그것은 가버나움에서 와디 케라제(Wady Kerazeh) 위로 약 2 1/2마일 떨어진 현대의 케라제(Kerazeh)에 대한 일반적인 동의에 의해 확인되었습니다. 즉, Tell Hum입니다.","source_sha256":"cbfd380f4059435e6233f862258d850780b3b60789cb4d0e9a2cdcbd0ba23052","citation_candidates":[{"source":"Matt. 11:21","passage":"mat-11","verse":21,"ref":"mat-11:21","status":"KRV_VERIFIED","exact_korean_token":"고라신"},{"source":"Luke 10:13","passage":"luk-10","verse":13,"ref":"luk-10:13","status":"KRV_VERIFIED","exact_korean_token":"고라신"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0023","name_en":"Cilicia","name_ko":"길리기아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CILICIA","ko":"길리기아. 길리기아(Cilicia) 소아시아 남동쪽에 있는 해양 지방. 바울의 출생지인 다소는 주요 도시 중 하나였으며 유명한 철학 학교가 있었습니다. 이곳의 호화로운 기후는 마케도니아 제국과 합병된 후 많은 그리스 주민들을 끌어들였습니다. 그것은 B.C. 로마의 속주로 형성되었다. 67. 길리기아 유대인들은 예루살렘에 회당을 가지고 있었습니다(행 6:9). 바울은 회심한 직후 그곳을 방문했고(갈 1:21; 행 9:30), 다시 두 번째 선교 여행 중에(15:41) “수리아와 길리기아를 두루 다니며 교회들을 굳게 굳혔”습니다. 이곳은 실리시움(Cilicium)이라고 불리는 염소털 천으로 유명했습니다. 바울은 젊었을 때 이 천으로 천막 만드는 일을 배웠습니다.","source_sha256":"bde8ff30e4704186744747c9c983fc1c3e0644b440d64117c4fa85ac192283f0","citation_candidates":[{"source":"Acts 6:9","passage":"act-6","verse":9,"ref":"act-6:9","status":"KRV_VERIFIED","exact_korean_token":"길리기아"},{"source":"Gal. 1:21","passage":"gal-1","verse":21,"ref":"gal-1:21","status":"KRV_VERIFIED","exact_korean_token":"길리기아"},{"source":"Acts 9:30","passage":"act-9","verse":30,"ref":"act-9:30","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0024","name_en":"Corinth","name_ko":"고린도","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CORINTH","ko":"고린도. 고린도 펠로폰네소스 강과 그리스 본토를 연결하는 지협에 있는 그리스 도시. 아테네에서 서쪽으로 약 48마일 떨어져 있다. 고대 도시는 로마인에 의해 파괴되었으며(B.C. 146), 신약성서에 언급된 도시는 약 100년 후에 재건된 꽤 새로운 도시였으며 로마에서 온 자유민 식민지가 거주했습니다. 이곳은 로마 통치하에 남부 그리스 또는 아가야의 정부 소재지가 되었습니다(행 18:12-16). 그곳은 부와 사람들의 사치와 부도덕과 사악한 습관으로 유명했습니다. 로마인, 그리스인, 유대인이 혼합된 인구가 많았습니다. 바울이 처음으로 그 도시를 방문했을 때(서기 51년 또는 52년), 세네카의 형제 갈리오가 총독이었습니다. 여기서 바울은 18개월 동안 머물렀다(18:1-18). 여기서 그는 처음으로 아굴라와 브리스길라를 알게 되었고, 떠나고 얼마 지나지 않아 아볼로를 알게 되었습니다. 에베소에서 왔습니다. 얼마 후에 그는 두 번째로 그곳을 방문하여 석 달 동안 머물렀다(20:3). 이 두 번째 방문 동안에 그의 로마서가 기록되었습니다(아마 A.D. 55년). 고린도에는 많은 유대인 개종자가 있었지만 이방인의 요소가 그곳 교회에 만연했습니다. 일부는 고린도후서에서 주장했습니다. 12:14; 13:1, 바울은 세 번째로 고린도를 방문했다(즉, 기록되지 않은 어떤 기회에 그는 일반적으로 첫 번째 방문과 두 번째 방문이라고 불리는 기간 사이에 그 도시를 방문했다). 그러나 언급된 구절들은 단지 고린도를 방문하려는 바울의 의도(그리스어 현재 시제가 의도를 나타내는 고린도전서 16:5과 비교)를 나타낼 뿐인데, 그 의도는 어떤 면에서 좌절되었다. 우리는 사도가 그에 대해 더 분명하게 언급하지 않고서는 그러한 방문을 할 수 없었다고는 거의 상상할 수 없습니다.","source_sha256":"80eea674c30428d08beb1c83c1f628f480989de6c2901d53a6b2f48c9876375e","citation_candidates":[{"source":"Acts 18:12-16","passage":"act-18","verse":12,"ref":"act-18:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Cor. 12:14","passage":"2co-12","verse":14,"ref":"2co-12:14","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Cor. 16:5","passage":"1co-16","verse":5,"ref":"1co-16:5","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0025","name_en":"Crete","name_ko":"그레데","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CRETE","ko":"크레타 섬. 크레타 섬은 현재 지중해에서 가장 큰 섬 중 하나인 칸디아(Candia)라고 불리며 길이가 약 140마일, 너비가 35마일입니다. 그 섬은 한때 “백 개의 도시”가 있는 매우 번영하고 인구가 많은 섬이었습니다. 사람들의 성격은 바울이 디도서에 보낸 서한에서 “그들의 시인 중 한 사람”(에피메니데스)의 말을 인용한 데 묘사되어 있습니다. “그레데인들은 항상 거짓말쟁이요 악한 짐승이요 배만 위하는 게으른 자들이니라”(디도서 1:12). 오순절 날 그레데 출신의 유대인들이 예루살렘에 있었습니다(행 2:11). 바울이 로마로 항해할 때 이 섬을 방문했습니다(행 27장). 여기서 바울은 이어서 “장로들을 성임하기 위해” 디도를 떠났습니다(1:5). 어떤 사람들은 그곳이 갑도림(q.v.)이나 블레셋 사람들의 원래 고향이었다고 생각합니다.","source_sha256":"a43e3f9e5988f3ee7f6daef83323d5454e69f1e28f19b34c3c99650ea8ab6eaa","citation_candidates":[{"source":"Titus 1:12","passage":"tit-1","verse":12,"ref":"tit-1:12","status":"KRV_VERIFIED","exact_korean_token":"그레데"},{"source":"Acts 2:11","passage":"act-2","verse":11,"ref":"act-2:11","status":"KRV_VERIFIED","exact_korean_token":"그레데"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0026","name_en":"Cyprus","name_ko":"구브로","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CYPRUS","ko":"키프로스. 키프로스 길이가 약 148마일, 폭이 40마일인 지중해에서 가장 큰 섬 중 하나입니다. 시리아 해안에서 약 60마일 떨어져 있다. 구약의 “깃딤”이었습니다(민 24:24). 그리스 식민지 개척자들은 이 섬에서 자란 키프로스, 즉 헤나(캄파이어 참조)에서 유래한 키프로스(Kypros)라는 이름을 붙였습니다. 원래 페니키아인들이 거주했던 곳이었습니다. 기원전 477년에는 그리스의 지배를 받게 되었다. 그리고 기원전 로마의 속주가 되었습니다. 58. 고대에는 이곳이 큰 상업 활동의 중심지였습니다. 옥수수와 포도주와 기름이 이곳에서 가장 완벽하게 생산되었습니다. 목재와 광물도 풍부했습니다. 이곳은 신약성경(행 4:36)에 바나바의 출신지로 처음 언급됩니다. 이곳은 바울과 바나바, 요한 마가가 파송된 첫 번째 선교 사업의 현장이었습니다(13:4-13). 안디옥 교회에서. 그 후에 바나바와 마가만이 그곳을 방문했습니다(15:39). 아마도 오순절에 이 섬에 속했던 개종자 중 한 사람인 “오래된 제자” 음나손이 언급되어 있습니다(21:16). 이것은 또한 바울의 항해와 관련하여 언급되기도 한다(행 21:3; 27:4). 300년 동안 투르크의 지배를 받았다가 1878년 영국 정부에 넘겨졌습니다.","source_sha256":"26b2fbeb83a4b66e5d283c8f677cf1a87315264be85400bf8edda67c3b086807","citation_candidates":[{"source":"Num. 24:24","passage":"num-24","verse":24,"ref":"num-24:24","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Acts 4:36","passage":"act-4","verse":36,"ref":"act-4:36","status":"KRV_VERIFIED","exact_korean_token":"구브로"},{"source":"Acts 21:3","passage":"act-21","verse":3,"ref":"act-21:3","status":"KRV_VERIFIED","exact_korean_token":"구브로"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0027","name_en":"Cyrene","name_ko":"구레네","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-CYRENE","ko":"키레네. 키레네(Cyrene) 북아프리카 어퍼리비아에 있는 도시(현재의 트리폴리). 그리스인의 식민지(B.C. 630)에 의해 건설됨. 나중에는 라구스(Lagus)의 아들 프톨레마이오스(Ptolemy)가 그 도시의 안전에 기여할 것이라고 생각하여 그 도시에 소개한 많은 수의 유대인들이 포함되어 있었습니다. 그들은 수와 영향력이 증가했습니다. 그리하여 우리는 기독교의 초기 역사와 관련하여 그것들을 자주 언급할 준비가 되어 있습니다. 우리 주님의 십자가를 짊어진 시몬도 이곳 출신이었습니다(마 27:32, 막 15:21). 구레네 출신 유대인들은 오순절에 예루살렘에 있었습니다(행 2:10). 그리고 구레네 유대인들은 예루살렘에 회당을 가지고 있었습니다(6:9). 구레네에 속한 개종자들은 안디옥에 최초의 이방인 교회가 형성되는 데 기여했습니다(11:20). “안디옥에서 주를 섬기던” “선지자들과 교사들” 중에는 구레네 사람 루기오도 있었습니다 (13:1).","source_sha256":"04df3a6e20e93ddbdffa45609af0b4b323d3bd10de51b8b5dfcd93d5390b1618","citation_candidates":[{"source":"Matt. 27:32","passage":"mat-27","verse":32,"ref":"mat-27:32","status":"KRV_VERIFIED","exact_korean_token":"구레네"},{"source":"Mark 15:21","passage":"mrk-15","verse":21,"ref":"mrk-15:21","status":"KRV_VERIFIED","exact_korean_token":"구레네"},{"source":"Acts 2:10","passage":"act-2","verse":10,"ref":"act-2:10","status":"KRV_VERIFIED","exact_korean_token":"구레네"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0028","name_en":"Decapolis","name_ko":"데가볼리","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-DECAPOLIS","ko":"데카폴리스. 데가볼리 열 도시 = 데가(열)와 폴리(폴리스)는 갈릴리 바다 동쪽과 남동쪽 지역으로 “열 성읍”을 포함하며 주로 헬라인들이 거주했습니다. 이곳은 바산과 길르앗의 일부를 포함하고 있으며 신약성경에 세 번 언급됩니다(마 4:25; 막 5:20; 7:31). 이 도시들은 스키토폴리스, 즉 “스키타이인의 도시”(고대 벳스안, 요르단 서쪽에 있는 10개의 도시 중 유일한 도시), 히포스, 가다라, 펠라(예루살렘 멸망 직전에 그리스도인들이 도망한 곳), 빌라델비아(고대 랍바스암몬), 거라사, 디온, 가나타, 라파나, 다마스쿠스였다. 로마인들이 시리아를 정복했을 때(기원전 65년) 그들은 이 “열 도시”를 재건하고 특정한 특권을 부여했으며, 그들과 연결된 속주를 “데가볼리”라고 불렀습니다.","source_sha256":"1e2fa5c9e8728aa2c382b4f4438a97ee880ca7e31f1cce610b147e5850cdf2ef","citation_candidates":[{"source":"Matt. 4:25","passage":"mat-4","verse":25,"ref":"mat-4:25","status":"KRV_VERIFIED","exact_korean_token":"데가볼리"},{"source":"Mark 5:20","passage":"mrk-5","verse":20,"ref":"mrk-5:20","status":"KRV_VERIFIED","exact_korean_token":"데가볼리"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0029","name_en":"Derbe","name_ko":"더베","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-DERBE","ko":"데르베. 더베(Derbe) 리스트라에서 약 20마일 떨어진 리가오니아 고지대 평야의 동쪽 부분에 있는 작은 마을입니다. 바울은 길리기아에서 이고니온으로 가는 길, 2차 선교 여행(행 16:1), 그리고 아마도 3차 여행(18:23, 19:1)에서 더베를 통과했습니다. 그의 첫 번째 여행에서(14:20, 21) 그는 반대편에서 더베로 왔다. 즉, Iconium에서. 그곳은 바울의 동료 중 한 사람인 가이오의 고향이었습니다(20:4). 그는 여기서 박해를 받지 않았습니다(딤후 3:11).","source_sha256":"0cb35bae8427c459822fb733f6569f9e21f4a05dfb63a088bfa80c04950a90a5","citation_candidates":[{"source":"Acts 16:1","passage":"act-16","verse":1,"ref":"act-16:1","status":"KRV_VERIFIED","exact_korean_token":"더베"},{"source":"2 Tim. 3:11","passage":"2ti-3","verse":11,"ref":"2ti-3:11","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0030","name_en":"Dothan","name_ko":"도단","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-DOTHAN","ko":"도단. 도단 두 우물, 요셉이 양 떼를 지키고 있는 형들을 발견한 유명한 목초지. 여기서 유다의 제안으로 그들은 그를 이스마엘 상인들에게 팔았습니다(창 37:17). 이는 BC주 기념물에 언급되어 있습니다. 1600. 이곳은 엘리사의 거주지였으며(왕하 6:13), 불병거와 불말이 그 도시가 서 있는 산을 둘러싸는 놀라운 환상의 장면이 있었습니다. 이곳은 길보아 언덕 사이, 사마리아에서 북쪽으로 약 12마일 떨어진 이스르엘 평원 남쪽에 있는 현대의 텔도단과 동일시됩니다. “두 개의 우물”은 여전히 ​​존재하며, 그 중 하나는 “요셉의 구덩이”(Jubb Yusuf)라는 이름을 갖고 있습니다.","source_sha256":"728c205ee7442752f653701a0909f4ba4f5cbf200747317323528753d2e11f61","citation_candidates":[{"source":"Gen. 37:17","passage":"gen-37","verse":17,"ref":"gen-37:17","status":"KRV_VERIFIED","exact_korean_token":"도단"},{"source":"2 Kings 6:13","passage":"2ki-6","verse":13,"ref":"2ki-6:13","status":"KRV_VERIFIED","exact_korean_token":"도단"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0031","name_en":"En-gedi","name_ko":"엔게디","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ENGEDI","ko":"엔게디. 엔게디 새끼 염소의 샘. 유다 광야(수 15:62), 사해 서쪽 해안(겔 47:10)에 위치하며 양쪽 끝에서 거의 같은 거리에 있다. 다윗은 사울이 두려워 이 마을 근처의 광야로 도망했습니다(수 15:62; 삼상 23:29). 처음에는 아모리 족속의 성읍 하사손다말(창 14:7)로 불렸다. 엔게디 포도원은 솔로몬 시대에 기념되었습니다(아 1:4). 현대판 '아인지디' 입니다. 그 이름이 유래된 \"분수\"는 바다 위 약 600피트의 산기슭에 솟아 있으며, 급격하게 내려가면서 주변에 화려함을 퍼뜨립니다. 강둑을 따라 오셔가 풍부하게 자랍니다. Porter는 그 관목을 이렇게 묘사합니다: \"줄기는 튼튼하고 직경이 거의 1피트에 달하며, 식물의 높이는 15피트 이상까지 자랍니다. 껍질은 회색이고 긴 타원형입니다. 잎은 부러지면 유백색 액체가 배출됩니다. 열매는 사과와 비슷하며 2~3개의 송이로 달려있습니다. 익으면 진한 노란색을 띠지만, 누르면 퍼프볼처럼 터집니다. 주로 공기로 가득 차 있는데...이것이 소위 '소돔의 사과'이다.” 사마리아 등을 통해서(사과 참조)","source_sha256":"a976fdc38e335e99e6e9deb37ae9b7aaeac4d974b282d7cd610d24aa300eed5c","citation_candidates":[{"source":"Josh. 15:62","passage":"jos-15","verse":62,"ref":"jos-15:62","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Ezek. 47:10","passage":"ezk-47","verse":10,"ref":"ezk-47:10","status":"KRV_VERIFIED","exact_korean_token":"엔게디"},{"source":"1 Sam. 23:29","passage":"1sa-23","verse":29,"ref":"1sa-23:29","status":"KRV_VERIFIED","exact_korean_token":"엔게디"},{"source":"Gen. 14:7","passage":"gen-14","verse":7,"ref":"gen-14:7","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0032","name_en":"Emmaus","name_ko":"엠마오","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-EMMAUS","ko":"엠마오. 예루살렘에서 “육십 스타디온” 떨어진 마을인 엠마오 온천. 그곳에서 우리 주님은 부활하신 날 두 제자와 인터뷰를 하셨습니다(누가복음 24:13). 이것은 예루살렘에서 북서쪽으로 7마일 이상 떨어진 현대의 엘쿠베이베와 동일시됩니다. \"작은 돔\"을 의미하는 엘 쿠베이베라는 이름은 아직 그곳에서 발견되지 않은 십자군 교회의 유적에서 유래되었습니다. 다른 사람들은 그것을 현대의 쿠르베 카마사, 즉 예루살렘에서 남서쪽으로 약 8마일 떨어진 곳에 있는 \"카마사의 폐허\"와 동일시하며, 그곳에는 십자군 교회의 폐허도 있습니다. 그러나 해당 사이트는 많은 논란을 불러일으켰습니다.","source_sha256":"c4ce4bb3916f23f1de624d1ef2c61721892e5c90c64c54a34f097ba1b9bd94af","citation_candidates":[{"source":"Luke 24:13","passage":"luk-24","verse":13,"ref":"luk-24:13","status":"KRV_VERIFIED","exact_korean_token":"엠마오"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0033","name_en":"Endor","name_ko":"엔돌","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ENDOR","ko":"엔도르. 엔도르의 분수; 즉 “시대의”, 드보라와 바락이 시스라와 야빈을 상대로 얻은 큰 승리의 현장과 가까운 잇사갈 지역(수 17:11)의 한 장소(시 83:9,10을 비교하라). 사울은 블레셋 사람들과의 마지막 전투 전날 밤 마녀로 알려진 사람에게 문의하여 엔돌에게 의뢰했습니다(삼상 28:7). 이 마을은 이스르엘에서 약 7마일 떨어진 리틀 헤르몬의 북쪽 경사면에 있는 현대의 엔두르 마을과 동일시되는데, 이 마을은 “약 20채 정도의 집 또는 오두막으로 이루어진 더러운 마을이며, 대부분이 폐허가 되어 버렸습니다.”","source_sha256":"99f0bb5f646dbc8ba4e0d58b04cfd2c717a31cecadc36c17accfbad2018fe614","citation_candidates":[{"source":"Josh. 17:11","passage":"jos-17","verse":11,"ref":"jos-17:11","status":"KRV_VERIFIED","exact_korean_token":"엔돌"},{"source":"Ps. 83:9","passage":"psa-83","verse":9,"ref":"psa-83:9","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 28:7","passage":"1sa-28","verse":7,"ref":"1sa-28:7","status":"KRV_VERIFIED","exact_korean_token":"엔돌"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0035","name_en":"Ezion-geber","name_ko":"에시온게벨","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-EZION-GEBER","ko":"에시온게베르. 에시온게벨 거인의 등뼈(바다로 뻗어나가는 산 꼭대기에서 소위 부름), 엘랏 또는 엘롯 근처 아카바 만, 홍해의 엘라니 지류 북동쪽 끝에 있는 고대 도시이자 항구(민 33:35; 신 2:8). 여기에서 솔로몬은 두로에서 다시스까지 그리고 서쪽에서 오빌과 무역했던 배들, 즉 “다시스 배들”을 건조했습니다(왕상 9:26; 대하 8:17). 그리고 여기서도 여호사밧의 함대가 파선하였다(왕상 22:48; 대하 20:36). 그 성읍은 인구가 많은 성읍이 되었고 많은 유대인이 그곳에 정착하였다(왕하 16:6, “엘랏”). 고대에는 만의 북쪽 끝이 지금보다 더 멀리 아라바의 마른 바닥에서 위로 10마일 떨어진 아인 엘 구디얀까지 흘러들어갔고 에시온게벨도 거기에 있었을 것으로 추정됩니다.","source_sha256":"1a3816a7c099917bbd849b10d4627f8e0879bf6f5e0988554099a53101f05e9e","citation_candidates":[{"source":"Num. 33:35","passage":"num-33","verse":35,"ref":"num-33:35","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"Deut. 2:8","passage":"deu-2","verse":8,"ref":"deu-2:8","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Kings 9:26","passage":"1ki-9","verse":26,"ref":"1ki-9:26","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"2 Chr. 8:17","passage":"2ch-8","verse":17,"ref":"2ch-8:17","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"1 Kings 22:48","passage":"1ki-22","verse":48,"ref":"1ki-22:48","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"2 Chr. 20:36","passage":"2ch-20","verse":36,"ref":"2ch-20:36","status":"KRV_VERIFIED","exact_korean_token":"에시온게벨"},{"source":"2 Kings 16:6","passage":"2ki-16","verse":6,"ref":"2ki-16:6","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0037","name_en":"Gadara","name_ko":"가다라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GADARA","ko":"가다라. 가다라 로마 페레아 지방의 수도. 그것은 갈릴리 바다에서 남동쪽으로 약 6마일 떨어진 산 정상에 서 있었습니다. 마가복음(5:1)과 누가복음(8:26-39)은 귀신들린 자(마태복음 [8:28-34]에서는 두 귀신들린 사람을 말함)를 고치는 기적이 “가다라 사람들의 지방에서” 일어난 것으로 묘사하여 그 장면을 전반적으로 묘사합니다. 기적은 가다라 자체에서 일어날 수 없었습니다. 왜냐하면 호수와 이 마을 사이에는 깊고 거의 지나갈 수 없는 Hieromax(Jarmuk) 계곡이 있기 때문입니다. 그것은 고대 가다라의 화려함을 증언하는 매우 광범위한 유적지로 둘러싸인 현대 마을인 움-케이스(Um-Keis)와 동일시됩니다. “가다라의 가장 흥미로운 유적은 주로 북동 경사면에 있는 도시 주변의 상당한 거리에 걸쳐 절벽에 점재해 있는 무덤입니다. 아름답게 조각된 석관이 주변 높이에 흩어져 있습니다. 그들은 석회암 암석에서 발굴되었으며, 일부는 평방 20피트가 넘는 다양한 크기의 방으로 구성되어 있으며 측면에 시체를 넣을 수 있는 오목한 부분이 있습니다... Um-Keis의 현재 주민들은 옛날의 불쌍한 미치광이들처럼 모두 혈거인이며 '무덤에 거주'하며 때로는 보호받지 못한 여행자에게도 거의 위험합니다.”","source_sha256":"e8f7dc11f41460ed88880ff142c39757f09973b79ea08e606e7fad7ff1d4b618","citation_candidates":[],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0038","name_en":"Gennesaret","name_ko":"게네사렛","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GENNESARET","ko":"게네사렛. 게네사렛은 풍요의 정원입니다. (1) 긴네렛이라고 불리는 납달리의 성읍(수 19:35), 때로는 복수형 긴네롯(11:2)으로 사용됨. 나중에 그 이름은 점차 게네살과 게네사렛으로 바뀌었습니다(눅 5:1). 이 도시는 그 이름이 붙여진 호수의 서쪽 기슭에 자리잡고 있었습니다. 그 어떤 흔적도 남지 않았습니다. 게네사렛 평야는 비옥하고 아름다워서 “갈릴리 낙원”이라고 불렸습니다. 현재는 엘 구웨이르(el-Ghuweir)라고 불립니다. (2.) 게네사렛 호수, 긴네렛의 헬라어 형태(q.v.). (갈릴리 바다 참조)","source_sha256":"1614ef87916c8015959543dbcdbf7040f4e108c69a4212e7bce7152509aac28a","citation_candidates":[{"source":"Josh. 19:35","passage":"jos-19","verse":35,"ref":"jos-19:35","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Luke 5:1","passage":"luk-5","verse":1,"ref":"luk-5:1","status":"KRV_VERIFIED","exact_korean_token":"게네사렛"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0039","name_en":"Gerar","name_ko":"그랄","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GERAR","ko":"그랄. 게라르 A 지역; 숙소. 팔레스타인 남쪽 경계에 있는 매우 오래된 도시와 지역으로, 아비멜렉이라는 왕이 통치했습니다(창 10:19; 20:1, 2). 아브라함이 여기에 머물렀고 아마 이삭도 이곳에서 태어났을 것입니다. 이 두 족장 모두 여기서 자기 아내를 부인하는 죄를 범하였고, 두 사람 모두 브엘세바로 떠나기 전에 왕과 조약을 맺었습니다(21:23-34, 26). 목축이 풍부한 나라였던 것 같습니다(대하 14:12-18). 여기서 이삭은 백 배의 수확을 거두었고 하나님의 축복을 받았습니다(창 26:12). “그랄 골짜기”(창 26:17)는 아마도 현대의 와디 엘예르드(Wady el-Jerdr)였을 것이다.","source_sha256":"555537f86c3f7289ed936e4dbaee39237d0b42590b3a2908dcd380136bf2d81e","citation_candidates":[{"source":"Gen. 10:19","passage":"gen-10","verse":19,"ref":"gen-10:19","status":"KRV_VERIFIED","exact_korean_token":"그랄"},{"source":"2 Chr. 14:12-18","passage":"2ch-14","verse":12,"ref":"2ch-14:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Gen. 26:12","passage":"gen-26","verse":12,"ref":"gen-26:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Gen. 26:17","passage":"gen-26","verse":17,"ref":"gen-26:17","status":"KRV_VERIFIED","exact_korean_token":"그랄"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0040","name_en":"Gezer","name_ko":"게셀","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GEZER","ko":"게셀. 게셀 절벽, 고대 가나안 왕실 도시(수 10:33; 12:12). 그 곳과 그 목초지는 고핫 자손 레위 사람들에게 할당되었다(21:21; 대상 6:67). 그것은 낮은 벳호론과 바다 사이에 서 있었다(수 16:3; 왕상 9:17). 이곳은 바알브라심 전투 이후 다윗이 블레셋 사람들을 추격한 마지막 지점이었습니다(삼하 5:25; 대상 14:16). 가나안 사람들은 솔로몬 시대까지 이 땅을 소유하고 있었는데, 이집트 왕이 그것을 빼앗아 솔로몬이 결혼한 이집트 공주의 지참금의 일부로 솔로몬에게 주었다(왕상 9:15-17). 그곳은 벳호론에서 남서쪽으로 약 10마일 떨어진 텔엘예셀과 동일시됩니다. 아마르나 서판에 언급되어 있습니다.","source_sha256":"53d1c17460d95fb1ba0133e923b3e787140c4102b41968edc2387911846f710a","citation_candidates":[{"source":"Josh. 10:33","passage":"jos-10","verse":33,"ref":"jos-10:33","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"1 Chr. 6:67","passage":"1ch-6","verse":67,"ref":"1ch-6:67","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"Josh. 16:3","passage":"jos-16","verse":3,"ref":"jos-16:3","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"1 Kings 9:17","passage":"1ki-9","verse":17,"ref":"1ki-9:17","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"2 Sam. 5:25","passage":"2sa-5","verse":25,"ref":"2sa-5:25","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"1 Chr. 14:16","passage":"1ch-14","verse":16,"ref":"1ch-14:16","status":"KRV_VERIFIED","exact_korean_token":"게셀"},{"source":"1 Kings 9:15-17","passage":"1ki-9","verse":15,"ref":"1ki-9:15","status":"KRV_VERIFIED","exact_korean_token":"게셀"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0042","name_en":"Gilboa","name_ko":"길보아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GILBOA","ko":"길보아. 길보아 끓는 샘, 산맥, 지금은 예벨후쿠아'로, 사울이 블레셋 사람들에게 참담한 패배를 당한 장면으로 기억에 남습니다. 여기서도 그의 세 아들이 죽임을 당했고 그 자신도 자기 손으로 죽었습니다(삼상 28:4; 31:1-8; 삼하 1:6-21; 21:12; 대상 10:1, 8). 그것은 동쪽의 에스드라엘론(이스르엘) 골짜기와 요단 골짜기 사이의 경계를 이루는 낮고 불모의 산이었습니다. 이 패배의 소식이 다윗에게 전달되었을 때, 그는 “활의 노래”(삼하 1:19-27)에서 그러한 애처로운 말을 전했습니다.","source_sha256":"221e743ff62aadaf4898e77158867072335d1f1b9aa2cdd17ab82ce79a33b4a7","citation_candidates":[{"source":"1 Sam. 28:4","passage":"1sa-28","verse":4,"ref":"1sa-28:4","status":"KRV_VERIFIED","exact_korean_token":"길보아"},{"source":"2 Sam. 1:6-21","passage":"2sa-1","verse":6,"ref":"2sa-1:6","status":"KRV_VERIFIED","exact_korean_token":"길보아"},{"source":"1 Chr. 10:1","passage":"1ch-10","verse":1,"ref":"1ch-10:1","status":"KRV_VERIFIED","exact_korean_token":"길보아"},{"source":"2 Sam. 1:19-27","passage":"2sa-1","verse":19,"ref":"2sa-1:19","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0043","name_en":"Golgotha","name_ko":"골고다","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GOLGOTHA","ko":"골고다. 골고다(Golgotha) 예수께서 십자가에 못 박히신 곳의 일반적인 이름. 전도자들은 이 단어를 “해골이 있는 곳”으로 해석합니다(마 27:33; 막 15:22; 요 19:17). 이 이름은 그리스어 문자로 된 아람어 굴갈다(Gulgaltha)를 나타내며 히브리어 굴골렛(민 1:2; 대상 23:3, 24; 왕하 9:35)은 “해골”을 의미합니다. 이것은 갈보리(갈보리)라는 단어와 동일합니다. 그것은 벌거벗은 해골처럼 둥근 작은 마당이었습니다. 그곳은 성문 밖(히 13:12 비교), 성 근처(눅 23:26), “동산”(요 19:41)이 있고 시골로 통하는 큰 길에 있는 잘 알려진 곳이었다는 것이 복음서 기자들에게 분명하다. 그러므로 그것이 현재의 “성묘 교회” 내에 수용된다는 것은 지지할 수 없는 생각입니다. 도시 북쪽에 있는 예레미야 동굴 위의 언덕은 아마도 갈보리의 진정한 장소. 언덕 남쪽 절벽에 있는 바위의 두개골 같은 모습은 매우 놀랍습니다.","source_sha256":"8621fbdb41f84a821e2b5d6a0c43355526044bd29ee22c3e52ba578a5f7b7a58","citation_candidates":[{"source":"Matt. 27:33","passage":"mat-27","verse":33,"ref":"mat-27:33","status":"KRV_VERIFIED","exact_korean_token":"골고다"},{"source":"Mark 15:22","passage":"mrk-15","verse":22,"ref":"mrk-15:22","status":"KRV_VERIFIED","exact_korean_token":"골고다"},{"source":"John 19:17","passage":"jhn-19","verse":17,"ref":"jhn-19:17","status":"KRV_VERIFIED","exact_korean_token":"골고다"},{"source":"Num. 1:2","passage":"num-1","verse":2,"ref":"num-1:2","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Chr. 23:3","passage":"1ch-23","verse":3,"ref":"1ch-23:3","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 9:35","passage":"2ki-9","verse":35,"ref":"2ki-9:35","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Heb. 13:12","passage":"heb-13","verse":12,"ref":"heb-13:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Luke 23:26","passage":"luk-23","verse":26,"ref":"luk-23:26","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"John 19:41","passage":"jhn-19","verse":41,"ref":"jhn-19:41","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0044","name_en":"Goshen","name_ko":"고센","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GOSHEN","ko":"고센. 고센 (1.) 야곱과 그의 가족이 정착하여 출애굽할 때까지 머물렀던 애굽의 한 지역(창 45:10; 46:28, 29, 31 등). 그곳은 “고센 땅”(47:27)으로 불리기도 하고, 간단히 “고센”(46:28), “라암셋 땅”(47:11; 출 12:37)이라고도 불리우는데, 이는 비돔과 라암셋 성읍이 그 경계 안에 있었기 때문이다. 또한 소안이나 타니스(시 78:12). 그것은 나일강 동쪽에 있었고 왕의 거주지에서 멀지 않은 것으로 보입니다. 그곳은 “땅의 가장 좋은 곳”이었지만(창 47:6, 11) 지금은 사막이 되었습니다. 이 내용은 요셉이 아버지에게 보낸 메시지에서 처음 언급되었습니다. 이곳은 삼각주 동부와 팔레스타인 서부 국경 사이에 위치한 현대의 와디 투밀라트(Wady Tumilat)와 동일시됩니다. 이곳은 왕의 가축 중 일부를 키우는 목축 지역이었습니다(창 47:6). 그 주민들은 전적으로 이스라엘 사람들만은 아니었습니다(출 3:22; 11:2; 12:35, 36). (2) 팔레스타인의 한 지역(수 10:41; 11:16). 그곳은 유다 해상 평야의 일부였으며 가사와 기브온 사이에 있었습니다. (3) 유다 산지에 있는 성읍(수 15:51).","source_sha256":"87b5cdc76fdc478fcf0be4eb6f97958730de8a65d1cd9e958369e4f7bd1f6d0c","citation_candidates":[{"source":"Gen. 45:10","passage":"gen-45","verse":10,"ref":"gen-45:10","status":"KRV_VERIFIED","exact_korean_token":"고센"},{"source":"Ps. 78:12","passage":"psa-78","verse":12,"ref":"psa-78:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Gen. 47:6","passage":"gen-47","verse":6,"ref":"gen-47:6","status":"KRV_VERIFIED","exact_korean_token":"고센"},{"source":"Josh. 10:41","passage":"jos-10","verse":41,"ref":"jos-10:41","status":"KRV_VERIFIED","exact_korean_token":"고센"},{"source":"Josh. 15:51","passage":"jos-15","verse":51,"ref":"jos-15:51","status":"KRV_VERIFIED","exact_korean_token":"고센"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0047","name_en":"Hazor","name_ko":"하솔","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-HAZOR","ko":"하조르. Hazor 동봉; 확고히 하는. (1) 메롬 호수 북쪽 산지에 있는 가나안 사람들의 요새(수 11:1-5). 야빈 왕은 그의 동맹 지파들과 함께 이곳에서 큰 전투에서 여호수아와 맞섰습니다. 여호수아는 눈에 띄는 승리를 거두었고, 이로써 사실상 가나안 정복이 완성되었습니다(11:10-13). 그러나 이 도시는 나중에 가나안 사람들에 의해 재건되었으며, 같은 세습 이름을 가진 야빈 왕이 다스렸습니다. 시스라라는 이름의 유명한 지도자가 이끄는 그의 군대는 그 나라를 완전히 정복하려는 목표를 가지고 남쪽을 휩쓸었습니다. 이 강력한 군대는 여선지자 드보라의 조언에 따라 나아갔던 바락 휘하의 이스라엘 사람들과 맞섰습니다. 그 결과는 구약에 기록된 이스라엘의 가장 놀라운 승리 중 하나였습니다(수 19:36; 삿 4:2; 삼상 12:9). 하솔 성이 함락되어 점령되었습니다. 이스라엘 사람들. 이 성은 시리아와 앗시리아가 왕국으로 들어가는 것을 막기 위해 솔로몬이 요새화했습니다. 앗수르 왕 디글랏 빌레셀이 그 땅을 침공했을 때, 이곳은 그가 점령한 첫 번째 성읍 중 하나였으며 그 주민들을 앗수르로 포로로 잡아갔습니다(왕하 15:29). Kedesh에서 남동쪽으로 2 1/2마일 떨어진 Khurbet Harrah로 확인되었습니다. (2) 유다 남쪽에 있는 도시(수 15:23). 여기서 이름은 아마도 “Hazor and Ithnan” 대신에 Ithnan, HAZOR-ITHNAN이라는 단어와 연결되어야 할 것입니다. (3) 아라비아의 한 지역(렘 49:28-33), 어떤 사람들은 이투라(즉, 이투라)라고 생각함. (4.) “그리옷과 헤스론”(수 15:25)은 “그리옷헤스론”(R.V.에서와 같이)이어야 하며, 두 이름은 한 장소의 이름(예: 기럇여아림과 같이)으로 함께 결합되어야 하고, “하솔도 그러하니라”(R.V.). 이 장소는 다음으로 확인되었습니다. el-Kuryetein은 가룟 유다의 고향으로 추정됩니다. (케리오스 참조)","source_sha256":"69c243e5bc488d13367ee81507fdef5be3dbd3e7cb52127c15d61481e4e23953","citation_candidates":[{"source":"Josh. 11:1-5","passage":"jos-11","verse":1,"ref":"jos-11:1","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"Josh. 19:36","passage":"jos-19","verse":36,"ref":"jos-19:36","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"Judg. 4:2","passage":"jdg-4","verse":2,"ref":"jdg-4:2","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"1 Sam. 12:9","passage":"1sa-12","verse":9,"ref":"1sa-12:9","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"2 Kings 15:29","passage":"2ki-15","verse":29,"ref":"2ki-15:29","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"Josh. 15:23","passage":"jos-15","verse":23,"ref":"jos-15:23","status":"KRV_VERIFIED","exact_korean_token":"하솔"},{"source":"Jer. 49:28-33","passage":"jer-49","verse":28,"ref":"jer-49:28","status":"KRV_VERIFIED","exact_korean_token":"하솔"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0048","name_en":"Iconium","name_ko":"이고니온","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ICONIUM","ko":"아이코니움. 이고니온 고대 리카오니아의 수도. 이곳은 사도의 1차 전도 여행 중에 비시디아 안디옥에서 바울과 바나바가 처음으로 방문한 곳이다(행 13:50, 51). 그곳에서 그들은 유대인들에게 박해를 받고 그 도시에서 쫓겨나 루스드라로 도망갔습니다. 그 후에 그들은 이고니온으로 돌아와 그곳에 세워진 교회를 격려했습니다(14:21,22). 아마도 바울이 실라와 함께 3차 전도 여행 중에 다시 그곳을 방문했을 것입니다(18:23). 그것은 지중해에서 내륙으로 약 120마일 떨어진 타우루스 산 기슭에 있는 현대의 코니에입니다.","source_sha256":"55df684c8892c11e6fad09a403334d77d5bb4d3743b835464134ebb53524d317","citation_candidates":[{"source":"Acts 13:50","passage":"act-13","verse":50,"ref":"act-13:50","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0050","name_en":"Jabbok","name_ko":"얍복","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-JABBOK","ko":"얍복. 얍복A는 요르단 동쪽에 있는 강 중 하나가 쏟아져 나오는 것, 즉 씨름하는 것입니다. 이 강은 갈릴리 바다와 사해 사이의 중간쯤, 즉 갈릴리 바다에서 약 45마일 아래로 떨어집니다. 길르앗 산의 동쪽에서 솟아올라 거칠고 깊은 계곡을 따라 약 65마일을 달린다. 이곳은 암몬 자손의 영토와 바산 왕 옥의 영토 사이의 경계였습니다(수 12:1-5; 민 21:24). 또한 르우벤 지파와 므낫세 반 지파 사이에도 있다(21:24; 신 3:16). 평야를 가로질러 서쪽으로 가는 과정에서 지하를 여러 번 통과합니다. \"강둑을 따라 펼쳐진 풍경은 아마도 팔레스타인에서 가장 아름다운 곳일 것입니다. 그리고 주변 산비탈에 우뚝 솟아 있는 도시와 마을, 요새의 폐허는 이 나라를 아름다운 만큼 흥미롭게 만듭니다.\" 이 강은 지금 Zerka 또는 푸른 강이라고 불립니다.","source_sha256":"0194c018edd4cd05aef16e44284da400772680ff2f36b146b26f9bc7d62d2a13","citation_candidates":[{"source":"Josh. 12:1-5","passage":"jos-12","verse":1,"ref":"jos-12:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Num. 21:24","passage":"num-21","verse":24,"ref":"num-21:24","status":"KRV_VERIFIED","exact_korean_token":"얍복"},{"source":"Deut. 3:16","passage":"deu-3","verse":16,"ref":"deu-3:16","status":"KRV_VERIFIED","exact_korean_token":"얍복"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0051","name_en":"Joppa","name_ko":"욥바","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-JOPPA","ko":"욥바. 욥바 뷰티(Joppa Beauty)는 단 지역(수 19:46; A.V., “야보”)에 있는 성읍으로 가이사랴와 가자 사이의 모래 곶에 있고 예루살렘에서 북서쪽으로 30마일 떨어진 곳에 있다. 아시아에서 가장 오래된 도시 중 하나이다. 이곳은 유대의 주요 항구였으며 지금도 그렇습니다. 페니키아인들로부터 결코 빼앗긴 적이 없습니다. 이곳은 기원전 2세기에야 유대인 도시가 되었습니다. 요나가 “여호와의 얼굴을 피하려고 배를 타고”(욘 1:3) 이 항구에서 왔습니다. 또한 히람의 사람들이 솔로몬을 위해 레바논에서 자른 나무를 수레에 실어 이곳으로 가져왔습니다(대하 2:16). 그리고 여기에 두 번째 성전 건축을 ​​위한 자재도 착륙했습니다(스 3:7). 베드로는 요파의 “바닷가” 무두장 시몬의 집에서 “여러 날 동안” 살았고 여기 “옥상”에서 “관용의 환상”을 보았습니다(행 9:36-43). 그것은 자파(Jaffa)라는 현대적인 이름으로, 투르크족이 통치하는 도시의 모든 노폐물과 불결함을 없애줍니다. “다른 어떤 도시도 그렇게 자주 전복되고, 약탈되고, 약탈되고, 불타고 재건된 적이 없습니다.” 현재 인구는 약 16,000명 정도라고 합니다. 이곳은 1799년 나폴레옹 휘하의 프랑스군이 점령했고, 나폴레옹은 이곳에서 4,000명의 포로를 학살하라는 명령을 내렸습니다. 이 도시는 국내에 존재하는 유일한 마차 도로와 1892년에 완공된 철도로 예루살렘과 연결되어 있습니다. 이는 B.C. 기념물에 나타나 있습니다. 1600-1300년, BC Sannacharib의 공격을 받았습니다. 702.","source_sha256":"0dc92ea8ef3de75a0b1ef5845803e95d98dae6b0268f303b93aa1bdfac4d52cb","citation_candidates":[{"source":"Josh. 19:46","passage":"jos-19","verse":46,"ref":"jos-19:46","status":"KRV_VERIFIED","exact_korean_token":"욥바"},{"source":"Jonah 1:3","passage":"jon-1","verse":3,"ref":"jon-1:3","status":"KRV_VERIFIED","exact_korean_token":"욥바"},{"source":"2 Chr. 2:16","passage":"2ch-2","verse":16,"ref":"2ch-2:16","status":"KRV_VERIFIED","exact_korean_token":"욥바"},{"source":"Ezra 3:7","passage":"ezr-3","verse":7,"ref":"ezr-3:7","status":"KRV_VERIFIED","exact_korean_token":"욥바"},{"source":"Acts 9:36-43","passage":"act-9","verse":36,"ref":"act-9:36","status":"KRV_VERIFIED","exact_korean_token":"욥바"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0053","name_en":"Kishon","name_ko":"기손","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-KISHON","ko":"기손. 팔레스타인 중부의 겨울 급류인 기손 굽이는 다볼과 길보아의 뿌리 부근에서 솟아올라 에스드라엘론과 아케 평야를 지나 북쪽 방향으로 지나가다가 갈멜 기슭에 있는 아코 만 북동쪽 모퉁이에서 지중해에 빠집니다. 그것은 에스드라엘론 평지와 그 주변 산들의 물이 바다로 흘러가는 배수구이다. 그것은 나흐르 엘 모카타(Nahr el-Mokattah), 즉 “살인의 강”이라는 현대적 이름을 지닌다(왕상 18:40을 비교하라). 드보라의 승리의 노래(삿 5:21)에서 이 강은 “옛 강”으로 언급되는데, 이는 (1) 오랜 세월 동안 흘렀기 때문이거나 (2) 타르굼에 따르면 “고대 이스라엘에게 표적과 기사를 보여준 급류”였기 때문입니다. 또는 (3) 아마도 그 언급은 고대인들 사이에서 그 지역의 착취에 대한 것일 것이다. 가나안 사람들은 인접한 에스드라엘론 평야가 팔레스타인의 큰 전쟁터였기 때문입니다. 이것은 시스라가 패배한 장면(삿 4:7, 13)과 엘리야가 바알 선지자들을 멸망시킨 장면(왕상 18:40)이었다. “키손 강이 최고조에 달했을 때, 부분적으로는 그 유사 때문에 후퇴하는 군대가 바다 자체를 통과할 수 없는 것처럼 느껴졌을 것입니다.” (데보라 참조)","source_sha256":"850ca72d893ce7a05bc5adaebff10d0b368ec8ed44a357bc95d77b71e09bc6f2","citation_candidates":[{"source":"1 Kings 18:40","passage":"1ki-18","verse":40,"ref":"1ki-18:40","status":"KRV_VERIFIED","exact_korean_token":"기손"},{"source":"Judg. 5:21","passage":"jdg-5","verse":21,"ref":"jdg-5:21","status":"KRV_VERIFIED","exact_korean_token":"기손"},{"source":"Judg. 4:7","passage":"jdg-4","verse":7,"ref":"jdg-4:7","status":"KRV_VERIFIED","exact_korean_token":"기손"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0054","name_en":"Laodicea","name_ko":"라오디게아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-LAODICEA","ko":"라오디게아. 라오디게아 성경에 언급된 이 이름의 도시는 에베소에서 동쪽으로 약 40마일 떨어진 리고 강둑에 있는 브루기아와 루디아 경계에 있었습니다(계 3:14). 원래는 디오폴리스라고 불렸고 그 다음에는 로아스라고 불렸으나 나중에는 시리아 왕 안티오코스 2세의 아내 라오디게아가 재건한 라오디게아라고 불렸습니다. 이곳은 소아시아에서 가장 중요하고 번성한 도시 중 하나였습니다. 아주 초기에 이곳은 기독교의 주요 중심지 중 하나가 되었습니다(골 2:1; 4:15; 계 1:11 등). 지금은 터키인들이 에스키히사르(Eski-hissar) 또는 “오래된 성”이라고 부르는 황폐한 곳이 되었습니다.","source_sha256":"1809acd2f63f72ecd3e76e538138118a2997b1c69b01c71735a99c168b3437f0","citation_candidates":[{"source":"Rev. 3:14","passage":"rev-3","verse":14,"ref":"rev-3:14","status":"KRV_VERIFIED","exact_korean_token":"라오디게아"},{"source":"Col. 2:1","passage":"col-2","verse":1,"ref":"col-2:1","status":"KRV_VERIFIED","exact_korean_token":"라오디게아"},{"source":"Rev. 1:11","passage":"rev-1","verse":11,"ref":"rev-1:11","status":"KRV_VERIFIED","exact_korean_token":"라오디게아"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0055","name_en":"Lydda","name_ko":"룻다","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-LYDDA","ko":"Lydda. 룻다 에브라임 지파의 한 마을로 신약성서(행 9:32, 35, 38)에만 베드로가 중풍병자 애니아를 고치는 기적의 장면이 언급된 곳입니다. 그곳은 욥바에서 동쪽으로 약 9마일 떨어진 항구에서 예루살렘으로 가는 길목에 있었습니다. 구약에서는(대상 8:12) 로드라고 불린다. 로마인에 의해 불탔으나 나중에 재건되어 디오폴리스라는 이름으로 알려졌습니다. 현대 이름은 러드(Ludd)입니다. 소위 영국의 수호성인인 성 조지(St. George)가 이곳에서 태어났다고 합니다.","source_sha256":"3f1d9e8d4d65b654f505bf172f9ad047dec2e7976edf210b6295e3bd1a1ff3c0","citation_candidates":[{"source":"Acts 9:32","passage":"act-9","verse":32,"ref":"act-9:32","status":"KRV_VERIFIED","exact_korean_token":"룻다"},{"source":"1 Chr. 8:12","passage":"1ch-8","verse":12,"ref":"1ch-8:12","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0056","name_en":"Lystra","name_ko":"루스드라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-LYSTRA","ko":"리스트라. 리스트라(Lystra) 소아시아 리카오니아(Lycaonia)의 마을로, 야생 지역에 있고 거친 인구가 사는 곳입니다. 바울은 이고니온에서 박해를 받은 후 이곳에서 복음을 전파했습니다(행 14:2-7). 여기서도 그는 저는 사람을 고쳤으며(8), 그리하여 무지하고 미신적인 사람들에게 깊은 인상을 주었기 때문에 그들은 그를 수성으로 여겼습니다. 왜냐하면 그가 “주요 설교자”였기 때문이고, 그의 동료 바나바는 유피테르로 여겼는데, 아마도 그의 위엄 있고 존경할 만한 외모 때문이었을 것입니다. (13절) 바울이 그들에게 간절히 말하여 모든 복의 근원이신 하나님께로 그들의 주의를 돌이켰더라. 그러나 얼마 지나지 않아 비시디아와 이고니온 안디옥 출신 유대인들의 영향으로 그들은 바울을 돌로 쳐서 죽게 내버려 두었습니다(14:19). 회복되자 바울은 더베로 떠났습니다. 곧 루스드라로 다시 돌아와서 그들을 격려하였으니 제자들은 그곳에서 확고함을 유지해야 합니다. 아마도 그는 세 번째 선교 여행 중에 이 도시를 다시 방문했을 것입니다(행 18:23). 아마도 이곳에서 태어났을 디모데(딤후 3:10, 11)는 이 기회에 리스트라에서 바울의 박해와 그의 용기를 목격한 사람들 중 하나였을 것임에 틀림없다.","source_sha256":"e45312976022dcf40c4aaca95fc1b2bed3f520adce7238b7cac95a73d6bd27d2","citation_candidates":[{"source":"Acts 14:2-7","passage":"act-14","verse":2,"ref":"act-14:2","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Acts 18:23","passage":"act-18","verse":23,"ref":"act-18:23","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Tim. 3:10","passage":"2ti-3","verse":10,"ref":"2ti-3:10","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0057","name_en":"Magdala","name_ko":"막달라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MAGDALA","ko":"막달라. 막달라 망대, 갈릴리에 있는 마을, 마태복음에만 언급됨. 15:39. 마가복음 8장 10절의 평행 구절에서 이곳은 달마누다라고 불린다. 이곳은 막달레나 또는 막달라 마리아라고 불리는 마리아의 탄생지였습니다. 그곳은 티베리아스 호수의 서쪽 기슭에 있었고 지금은 아마도 티베리아스에서 북서쪽으로 약 3마일 떨어진 엘-메델(el-Mejdel)이라는 작고 알려지지 않은 마을일 것입니다. 탈무드에서는 이 도시를 “색채의 도시”라고 부르며, 그 도시의 특정 지역을 “염색자의 탑”이라고 불렀습니다. 이곳에서는 쪽나무가 많이 재배되었습니다.","source_sha256":"5093dddebfa7aa3a1bd766f9b3f090051ebfdfa864e160050e60c1930838db5b","citation_candidates":[{"source":"Matt. 15:39","passage":"mat-15","verse":39,"ref":"mat-15:39","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Mark 8:10","passage":"mrk-8","verse":10,"ref":"mrk-8:10","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0059","name_en":"Mahanaim","name_ko":"마하나임","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MAHANAIM","ko":"마하나임. 마하나임 두 진영, 요단강 건너편 얍복 근처에 있는 곳. 이곳에서 야곱은 “하나님의 사자들”을 만났고, 밧단아람에서 돌아올 때 그의 일행을 “두 군대”로 나누었습니다(창 32:2). 이 이름은 나중에 그 장소에 건설된 마을에 붙여졌습니다. 그곳은 바산의 남쪽 경계였으며(수 13:26, 30) 레위 사람들의 성읍이 되었다(21:38). 이곳에서는 사울의 아들 이스보셋이 통치했고(삼하 2:8, 12), 다윗은 헤브론에서 통치했습니다. 여기에서도 혼란스러운 통치 후에 이스보셋은 자신의 경호원 두 명에 의해 살해당했습니다(삼하 4:5-7). 그들은 헤브론에 있는 다윗에게 그의 머리를 가져왔지만, 그들의 냉혹한 살인으로 인해 보상을 받는 대신에 다윗에게 죽임을 당했습니다. 그 후 여러 해가 지나서 다윗은 그의 아들 압살롬의 반역을 피해 예루살렘에서 도망쳤을 때, 바르실래가 자신을 대접했던 마하나임을 그의 소유로 삼았습니다. 그는 압살롬 주위에 모인 군대에 맞서기 위해 군대를 집결시켰습니다. 두 군대 사이의 크고 결정적인 전투와 그의 아들 압살롬의 죽음에 대한 소식이 그에게 도달한 것은 이 성문에 앉아 있을 때 그가 가장 극심한 슬픔에 빠졌을 때였습니다(삼하 17:24-27). 마하나임에 대한 유일한 다른 언급은 솔로몬의 납품업자 중 한 사람의 지위라는 것입니다(왕상 4:14). 그것은 얍복 남쪽, 에스살트 북동쪽의 브누엘 근처, 엘부키에아('작은 골짜기')라고 불리는 우울한 평야에서 발견된 폐허인 현대의 무후마와 동일시된다.","source_sha256":"3602d64abdfb67f4a47956f3ee5eb745bf41463c45e131ada5334bbf6aaeb1c0","citation_candidates":[{"source":"Gen. 32:2","passage":"gen-32","verse":2,"ref":"gen-32:2","status":"KRV_VERIFIED","exact_korean_token":"마하나임"},{"source":"Josh. 13:26","passage":"jos-13","verse":26,"ref":"jos-13:26","status":"KRV_VERIFIED","exact_korean_token":"마하나임"},{"source":"2 Sam. 2:8","passage":"2sa-2","verse":8,"ref":"2sa-2:8","status":"KRV_VERIFIED","exact_korean_token":"마하나임"},{"source":"2 Sam. 4:5-7","passage":"2sa-4","verse":5,"ref":"2sa-4:5","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Sam. 17:24-27","passage":"2sa-17","verse":24,"ref":"2sa-17:24","status":"KRV_VERIFIED","exact_korean_token":"마하나임"},{"source":"1 Kings 4:14","passage":"1ki-4","verse":14,"ref":"1ki-4:14","status":"KRV_VERIFIED","exact_korean_token":"마하나임"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0060","name_en":"Megiddo","name_ko":"므깃도","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MEGIDDO","ko":"므깃도. 므깃도는 원래 가나안 사람들의 왕도 중 하나였던(수 12:21) 군대의 장소였으며(수 12:21) 므낫세 지파에 속했지만(삿 1:27), 솔로몬 시대까지는 이스라엘 사람들이 완전히 차지하지 않았던 것 같다(왕상 4:12; 9:15). 므깃도 골짜기 또는 평야는 팔레스타인의 큰 전쟁터인 에스드라엘론 평야의 일부였습니다. 이곳에서 바락은 하솔 왕 야빈을 물리치고 그의 장군 시스라가 적군을 이끌었던 곳에서 주목할 만한 승리를 거두었습니다. 바락은 북쪽 지파들의 용사들을 모아 여선지자 드보라(q.v.)의 격려를 받아 대평원에서 가나안 사람들을 공격했습니다. 시스라의 군대는 완전히 혼란에 빠졌고, 기손 강물이 솟아올라 그 강둑에 넘치게 되었습니다(삿 4:5). 그로부터 오랜 세월이 흐른 후(BC 610) 바로네초는 II. 아시리아 왕을 대항하여 행진하면서 블레셋 평야와 샤론 평지를 통과했습니다. 그리고 요시야 왕은 므깃도 평야에서 그의 전진을 막으려 했으나 이집트인들에게 패배했습니다. 그는 전쟁에서 부상을 입었고, 예루살렘을 향해 병거에 실려 갈 때 죽었습니다(왕하 23:29; 대하 35:22-24). 온 이스라엘이 그를 위해 애도했습니다. 이 애도는 너무나 일반적이고 쓰디쓴 것이었기 때문에 스가랴(12:11, 12)가 암시하는 잠언이 되었습니다. 므깃도는 기손 강의 머리, 갈멜의 북동쪽 벼랑 아래, 에스드라엘론 평야의 남서쪽 가장자리, 이스르엘에서 서쪽으로 9마일 떨어진 곳에 있는 현대의 엘레준과 동일시된다. 다른 사람들은 이곳이 베스시안에서 남서쪽으로 4마일 떨어진 무제다(Mujedd'a)라고 생각하지만, 그 장소가 무엇인지는 아직 확실하지 않습니다.","source_sha256":"853b0f2ade4e9cee6e131cf7c34e98026b648bd77ccae3b0c57efe68298779d6","citation_candidates":[{"source":"Josh. 12:21","passage":"jos-12","verse":21,"ref":"jos-12:21","status":"KRV_VERIFIED","exact_korean_token":"므깃도"},{"source":"Judg. 1:27","passage":"jdg-1","verse":27,"ref":"jdg-1:27","status":"KRV_VERIFIED","exact_korean_token":"므깃도"},{"source":"1 Kings 4:12","passage":"1ki-4","verse":12,"ref":"1ki-4:12","status":"KRV_VERIFIED","exact_korean_token":"므깃도"},{"source":"Judg. 4:5","passage":"jdg-4","verse":5,"ref":"jdg-4:5","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 23:29","passage":"2ki-23","verse":29,"ref":"2ki-23:29","status":"KRV_VERIFIED","exact_korean_token":"므깃도"},{"source":"2 Chr. 35:22-24","passage":"2ch-35","verse":22,"ref":"2ch-35:22","status":"KRV_VERIFIED","exact_korean_token":"므깃도"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0061","name_en":"Miletus","name_ko":"밀레도","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MILETUS","ko":"밀레투스. 밀레투스(밀레툼, 딤후 4:20)는 에베소에서 남쪽으로 약 36마일 떨어진 항구 도시이자 이오니아의 고대 수도였습니다. 그리스에서 시리아로 항해하는 동안 바울은 이 항구에 닿았고 사도행전 20:15-35에 기록된 에베소 장로들(“장로들”, 28절)에게 그 고귀하고 애처로운 연설을 전달했습니다. 밀레토스 유적지는 현재 해안에서 약 10마일 떨어져 있습니다. (에베소서, 서한 참조)","source_sha256":"3f01451cecc3134f1280ee640aea5dc6a60e6d12462ea7649bc7b413d9d62764","citation_candidates":[{"source":"2 Tim. 4:20","passage":"2ti-4","verse":20,"ref":"2ti-4:20","status":"KRV_VERIFIED","exact_korean_token":"밀레도"},{"source":"Acts 20:15-35","passage":"act-20","verse":15,"ref":"act-20:15","status":"KRV_VERIFIED","exact_korean_token":"밀레도"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0063","name_en":"Nain","name_ko":"나인","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-NAIN","ko":"나인. 나인(히브리어 나인, “푸른 초장”, “사랑스러운”에서 유래), 예수께서 과부의 아들을 살리신 성문 근처의 마을 이름(누가복음 7:11-17). 이곳은 다볼에서 약 4마일, 가버나움에서 남서쪽으로 25마일 떨어진 예벨에드두히(=“모레 언덕” = “작은 헤르몬”)의 북서쪽 경사면에 위치한 네인이라는 마을과 동일시됩니다. 그것이 서 있는 경사면 기슭에는 에스드라엘론의 대평원이 있습니다. 이것은 우리 주님께서 행하신 죽은 자를 살리는 첫 번째 이적이었고, 사람들 사이에 큰 두려움과 놀라움을 불러일으켰습니다.","source_sha256":"bcaadeca830a36b3ac1b091e22d6b61512330760cd6adaafd4ca3ebed3240ec4","citation_candidates":[{"source":"Luke 7:11-17","passage":"luk-7","verse":11,"ref":"luk-7:11","status":"KRV_VERIFIED","exact_korean_token":"나인"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0066","name_en":"Patmos","name_ko":"밧모","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PATMOS","ko":"파트모스. 파트모스(Patmos) 에게해에 있는 “스포라데스(Sporades)”라고 불리는 그룹 중 하나인 바위가 많고 척박한 작은 섬. 이것은 성경에서 요한계시록 1:9에만 언급되어 있습니다. 요한이 도미티아누스 황제(AD 95)에 의해 추방되었던 이 섬에서 요한은 자신의 책에 기록된 놀라운 계시를 하나님으로부터 받았습니다. 이는 자연스럽게 역대 가장 깊은 관심을 가지고 투자하게 되었습니다. 지금은 파트모(Patmo)라고 불립니다. (존 참조)","source_sha256":"45e7f4bac86bb37d4f56f2a32c72a2c1368979a4f61772232057a1ee6618b67c","citation_candidates":[{"source":"Rev. 1:9","passage":"rev-1","verse":9,"ref":"rev-1:9","status":"KRV_VERIFIED","exact_korean_token":"밧모"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0068","name_en":"Pergamos","name_ko":"버가모","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PERGAMOS","ko":"버가모. 버가모는 소아시아 무시아의 주요 도시이다. “일곱 교회” 중 하나가 여기에 세워졌습니다(계 1:11, 2:17). 그곳은 사악함으로 유명하여 우리 주님께서 거기에 “사탄의 자리”가 있다고 말씀하셨습니다. 버가모 교회는 진리에서 벗어나 발람과 니골라당의 교리를 받아들인 것에 대해 책망을 받았습니다. 그리스도의 “충실한 순교자”인 안디바는 여기서 그의 피로 자신의 간증을 인봉하였습니다. 이 도시는 바다에서 약 20마일 떨어진 카이쿠스 강둑에 자리잡고 있었습니다. 현재는 베르가마(Bergama)라고 불리며, 인구는 약 2만 명에 달하며 그 중 약 2천 명이 기독교인이라고 공언합니다. 양피지(q.v.)는 이곳에서 처음으로 만들어졌으며 그리스인들은 도시 이름을 따서 페르가메네라고 불렀습니다.","source_sha256":"feff32cd0c3a1c0dd81e826e03606b898f3eea757e3e5a294b7413867226ff18","citation_candidates":[{"source":"Rev. 1:11","passage":"rev-1","verse":11,"ref":"rev-1:11","status":"KRV_VERIFIED","exact_korean_token":"버가모"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0069","name_en":"Philadelphia","name_ko":"빌라델비아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PHILADELPHIA","ko":"필라델피아. 필라델피아 형제애는 사디스에서 남동쪽으로 약 25마일 떨어진 소아시아 리디아의 도시입니다. 그곳은 “일곱 교회” 중 하나의 자리였습니다(계 3:7-12). 이곳은 서기 1392년에 투르크족의 소유가 되었습니다. 여러 차례 지진으로 거의 파괴될 뻔했습니다. 이곳은 여전히 ​​“신의 도시”라는 뜻의 알라쉐르(Allahshehr)라고 불리는 상당한 규모의 도시입니다.","source_sha256":"be03d1d85d282e5550abd96bb6eb4ccd3fe0282caca34796fb50eee7fd647506","citation_candidates":[{"source":"Rev. 3:7-12","passage":"rev-3","verse":7,"ref":"rev-3:7","status":"KRV_VERIFIED","exact_korean_token":"빌라델비아"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0070","name_en":"Philippi","name_ko":"빌립보","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PHILIPPI","ko":"빌립보. 빌립보 (1.) 이전에는 마케도니아 지방의 수도인 “샘”인 그레니데스. 그것은 Kavalla에서 북서쪽으로 약 8 마일 떨어진 바다 머리 근처에 서있었습니다. 지금은 Philibedjik이라는 폐허가 된 마을입니다. 마케도니아의 필립보(Philip of Macedonia)는 트라키아의 옛 도시 크레니데스(Crenides)를 요새화하고 자신의 이름을 따서 빌립보(B.C. 359-336)라고 불렀다. 아우구스투스 황제 시대에 이 도시는 로마 식민지, 즉 로마 군인들의 군사 정착지가 되었으며, 최근에 정복한 지역을 통제할 목적으로 그곳에 건설되었습니다. 그곳은 로마의 지방자치법에 따라 로마에서 직접 임명된 두움비리(duumviri)라고 불리는 군 장교들이 통치하는 “소형 로마”였습니다. 섭리의 인도를 받아 그곳으로 바울과 그의 동료 실라가 복음을 전하고 유럽 최초의 교회를 세웠습니다. (리디아 참조) 이 성공은 사람들의 적개심을 불러일으켰고 그들은 “부끄러운 일을” 당했습니다(행 16:9-40; 살전 2:2). 바울과 실라는 마침내 이 도시를 떠나 암비폴리스로 갔다(q.v.). (2.) 헤롯의 아들 분봉왕 빌립이 그의 왕국 북쪽 지역의 통치권을 계승했을 때, 그는 황제를 기리기 위해 파네아스라는 도시를 확장하고 그곳을 가이사랴라고 불렀습니다. 그러나 그는 그곳을 해안에 있는 가이사랴와 구별하기 위해 나중에 거기에 자신의 이름을 덧붙여 가이사랴-빌립보(q.v.)라고 불렀다.","source_sha256":"865792105c4de322798a7b0e2e82b22c7d3c2326fdbf1db5f040b51602171b8d","citation_candidates":[{"source":"Acts 16:9-40","passage":"act-16","verse":9,"ref":"act-16:9","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Thess. 2:2","passage":"1th-2","verse":2,"ref":"1th-2:2","status":"KRV_VERIFIED","exact_korean_token":"빌립보"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0071","name_en":"Pisidia","name_ko":"비시디아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PISIDIA","ko":"피시디아. 비시디아 밤빌리아 북쪽에 있는 소아시아 지역. 황소자리 산맥이 그것을 통해 확장됩니다. 바울은 주요 도시 중 하나인 안디옥을 두 번 방문했습니다(행 13:14; 14:21-24).","source_sha256":"d1e29e4fa3026f63fc31733e5c34cdc4e8fb1a2c3ba9228402f19312dcf0132e","citation_candidates":[{"source":"Acts 13:14","passage":"act-13","verse":14,"ref":"act-13:14","status":"KRV_VERIFIED","exact_korean_token":"비시디아"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0072","name_en":"Ptolemais","name_ko":"돌레마이","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PTOLEMAIS","ko":"프톨레마이스. 프톨레마이스 갈릴리의 해상 도시(행 21:7). 원래는 \"Accho\"(q.v.)라고 불렸으며 Ptolemy Soter가 Coele-Syria를 소유했을 때 Ptolemais라는 이름을 받았습니다.","source_sha256":"8ca1c973e5898d96501749635e945804613b43c6ef77b2f773d79316011bbd62","citation_candidates":[{"source":"Acts 21:7","passage":"act-21","verse":7,"ref":"act-21:7","status":"KRV_VERIFIED","exact_korean_token":"돌레마이"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0073","name_en":"Puteoli","name_ko":"보디올","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-PUTEOLI","ko":"푸테올리. 푸테올리(Puteoli) 캄파니아 해안에 있는 도시, 나폴리 만에서 북쪽으로 이어지는 만의 북쪽 기슭에 있는 도시. 바울이 로마로 가는 길에 상륙한 곳으로 그곳에서 170마일 떨어져 있습니다. 여기서 그는 7일 동안 머물렀다(행 28:13, 14). 이곳은 알렉산드리아 옥수수 선박의 대규모 백화점이었습니다. 여기서 바울과 그의 동료들은 “아피아 길”을 따라 로마로 여행을 시작했습니다. 지금은 포주올리(Pozzuoli)라고 불립니다. 거대한 원형 극장의 유적과 바울이 착륙했던 부두의 유적이 아직도 이곳에서 볼 수 있습니다.","source_sha256":"781a3cc1814dbeaf698f6a51e9db754d88ee0cd9a02a69774eb18668f0ea77d6","citation_candidates":[{"source":"Acts 28:13","passage":"act-28","verse":13,"ref":"act-28:13","status":"KRV_VERIFIED","exact_korean_token":"보디올"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0074","name_en":"Rabbah","name_ko":"랍바","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-RABBAH","ko":"랍바. Rabbah 또는 Rab'bath, 좋습니다. (1) “암몬 자손의 랍바”는 요단강에서 동쪽으로 약 20마일 떨어진 동쪽 언덕, 얍복 강과 합쳐지는 두 강 남쪽에 있는 암몬 사람들의 주요 도시이다. 여기에는 옥의 침상이 보존되어 있었는데(신 3:11), 아마도 암몬 사람들이 바산 왕을 상대로 승리를 거둔 데 대한 전리품이었을 것입니다. 다윗은 큰 전쟁에서 그들의 모든 동맹국을 굴복시킨 후, 그들의 도시를 점령하기 위해 강력한 군대와 함께 요압을 보냈습니다. 2년 동안 가해자들에 맞서 버텼습니다. 다윗이 그의 성격에 오점을 남기고 그의 남은 생애에 어둠을 드리우는 수치스러운 행위를 저지른 것은 그의 군대가 이 장기간의 포위 공격에 참여하고 있는 동안이었습니다. 마침내 “왕성”(혹은 “물의 성”, 삼하 12:27, 즉 강변의 낮은 성)을 취하여 성채), 요압은 최종 공격을 지휘하기 위해 다윗에게 사람을 보냈습니다(11:1; 12:26-31). 그 도시는 약탈당했고 백성들은 무자비하게 죽임을 당했습니다. “그가 암몬 자손의 모든 성읍에 이와 같이 행하였”습니다. 랍바의 멸망은 다윗의 마지막 정복이었다. 그의 왕국은 이제 한계에 도달했습니다(삼하 8:1-15; 대상 18:1-15). 이 도시의 함락은 아모스(1:14), 예레미야(49:2, 3), 에스겔(21:20; 25:5)에서 언급됩니다. (2.) 유다 산간지대에 있는 도시(수 15:60). 아마도 베이트지브린에서 북동쪽으로 6마일 떨어진 루바(Rubba) 폐허였을 것이다.","source_sha256":"c36df7c58fb916fe3434b5567b6e4b89d26abf85b2103234b0b4d51638b15f7f","citation_candidates":[{"source":"Deut. 3:11","passage":"deu-3","verse":11,"ref":"deu-3:11","status":"KRV_VERIFIED","exact_korean_token":"랍바"},{"source":"2 Sam. 12:27","passage":"2sa-12","verse":27,"ref":"2sa-12:27","status":"KRV_VERIFIED","exact_korean_token":"랍바"},{"source":"2 Sam. 8:1-15","passage":"2sa-8","verse":1,"ref":"2sa-8:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Chr. 18:1-15","passage":"1ch-18","verse":1,"ref":"1ch-18:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Josh. 15:60","passage":"jos-15","verse":60,"ref":"jos-15:60","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0075","name_en":"Ramoth-gilead","name_ko":"길르앗 라못","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-RAMOTH-GILEAD","ko":"라못-길르앗. 길르앗 라못은 요단 동편의 도피성 길르앗 고원이요 “길르앗 라못”으로 불렸다(신명기 4:43; 수20:8; 21:38). 이곳에서 아람 왕의 손에서 여호사밧을 구출하려고 여호사밧과 합류한 아합은 치명상을 입었습니다(왕상 22:1-36). 나중에 아하시야와 요람도 비슷한 시도를 하여 부상을 입었습니다(왕하 8:28). 이 성에서는 여호사밧의 아들 예후가 선지자의 생도 중 한 사람에게 기름 부음을 받았느니라(9:1,4). 그곳은 데가볼리의 도시 중 하나인 예라쉬나 게라사에서 서쪽으로 약 5마일 떨어진 얍복 북쪽 경사면에 있는 레이문과 동일시되었을 가능성이 높습니다. 다른 사람들은 그것을 에스살트(es-Salt)에서 북동쪽으로 약 25마일 떨어진 게로쉬(Gerosh)와 동일시하며, 또한 많은 사람들이 이를 동일시합니다. (라맛-미스베 참조)","source_sha256":"714b5dcf3e978cad5532fd8cc6d49edb7f1cf25c3b40d39eac6d70ad8a4f014b","citation_candidates":[{"source":"Deut. 4:43","passage":"deu-4","verse":43,"ref":"deu-4:43","status":"KRV_VERIFIED","exact_korean_token":"길르앗 라못"},{"source":"Josh. 20:8","passage":"jos-20","verse":8,"ref":"jos-20:8","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Kings 22:1-36","passage":"1ki-22","verse":1,"ref":"1ki-22:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 8:28","passage":"2ki-8","verse":28,"ref":"2ki-8:28","status":"KRV_VERIFIED","exact_korean_token":"길르앗 라못"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0079","name_en":"Salamis","name_ko":"살라미","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SALAMIS","ko":"살라미스. 살라미스 키프로스 남동쪽 해안에 있는 도시(행 13:5). 사울과 바나바가 1차 선교 여행 중에 유대인 회당 중 한 곳에서 말씀을 전파했는데, 그 곳에 여러 회당이 있었던 것 같다. 지금은 파마구스타(Famagusta)라고 불립니다.","source_sha256":"7cb1ba7555768570c0989b04f7f1a151d08f70753f0dc9c323f8d83b936d90ff","citation_candidates":[{"source":"Acts 13:5","passage":"act-13","verse":5,"ref":"act-13:5","status":"KRV_VERIFIED","exact_korean_token":"살라미"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0080","name_en":"Sardis","name_ko":"사데","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SARDIS","ko":"사디스. 사데(Sardis) 소아시아 리디아의 대도시. 그것은 트몰루스 산 기슭의 팍톨루스 강에 서 있었습니다. 여기에는 아시아 일곱 교회 ​​중 하나가 있었습니다(계 3:1-6). 지금은 Sert-Kalessi라는 폐허입니다.","source_sha256":"2c25b66fa4125f66f67d41d508143c5862dba87c17a20445e9a7da73dbb027db","citation_candidates":[{"source":"Rev. 3:1-6","passage":"rev-3","verse":1,"ref":"rev-3:1","status":"KRV_VERIFIED","exact_korean_token":"사데"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0081","name_en":"Smyrna","name_ko":"서머나","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SMYRNA","ko":"서머나. 서머나 미르(Smyrna Myrrh)는 에베소에서 북쪽으로 약 40마일 떨어진 소아시아 서부 해안에 있는 이오니아의 고대 도시입니다. 현재 이곳은 아나톨리아의 주요 도시로, 약 20만 명의 혼합 인구가 살고 있으며 그 중 약 3분의 1이 그리스도인이라고 공언하는 사람들입니다. 이곳에 설립된 교회는 우리 주님이 말씀하신 일곱 교회 ​​중 하나였습니다(계 2:8-11). 사도 요한의 제자이자 유명한 폴리캅은 2세기에 서머나 교회의 저명한 지도자였습니다. 여기서 그는 AD 155년에 순교하였다.","source_sha256":"38cde8df83783acf259c2158556b736f0437ab95b904bed776cd2a6c83046f9a","citation_candidates":[{"source":"Rev. 2:8-11","passage":"rev-2","verse":8,"ref":"rev-2:8","status":"KRV_VERIFIED","exact_korean_token":"서머나"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0082","name_en":"Succoth","name_ko":"숙곳","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SUCCOTH","ko":"숙곳. 숙곳 부스. (1) 이스라엘 사람들이 라암셋을 떠난 후 첫 번째 진을 쳤습니다(출 12:37). Pithom의 시민 이름 (q.v.). (2.) 얍복 북쪽 평야와 약 1마일 떨어진 곳에 있는 높은 둔덕이자 잔해 덩어리인 텔다랄라와 동일시되는 요단 동쪽에 있는 도시(수 13:27). 여기서 야곱(창 32:17, 30; 33:17)은 에서와 인터뷰한 후 밧단아람에서 돌아오는 길에 자신을 위해 집을 짓고 가축을 위한 초막을 만들었습니다. 이 도시의 방백들은 기드온과 그의 300명이 길보아에서 큰 승리를 거둔 후 도망하는 미디안 무리 중 하나를 따라갔을 때 “기절하면서도 추격”할 때 도움을 주기를 뻔뻔하게 거부했습니다. 카르코르에서 이 무리를 추월하고 패주시킨 후, 기디온은 돌아와서 도시의 통치자들을 방문하여 가혹한 처벌을 받았습니다. “그 성의 장로들과 가시덤불을 빼앗아 그는 광야와 찔레를 가지고 숙곳 사람들을 가르쳤습니다.”(삿 8:13-16) 이곳에는 성전의 금속을 주조하는 주조소가 세워졌습니다(왕상 7:46).","source_sha256":"b370fad427a7536099957243739971b1418663aae70eb377660f617370bf2ac7","citation_candidates":[{"source":"Josh. 13:27","passage":"jos-13","verse":27,"ref":"jos-13:27","status":"KRV_VERIFIED","exact_korean_token":"숙곳"},{"source":"Gen. 32:17","passage":"gen-32","verse":17,"ref":"gen-32:17","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Judg. 8:13-16","passage":"jdg-8","verse":13,"ref":"jdg-8:13","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Kings 7:46","passage":"1ki-7","verse":46,"ref":"1ki-7:46","status":"KRV_VERIFIED","exact_korean_token":"숙곳"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0083","name_en":"Sychar","name_ko":"수가","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SYCHAR","ko":"시차. 수가 거짓말쟁이 또는 술고래(참조 사 28:1, 7)는 십자군 시대부터 일반적으로 세겜이나 세겜과 동일시되었다(요 4:5). 그러나 최근 탐사 결과, 이곳은 야곱의 우물에서 북쪽으로 약 1마일 떨어진 에발 남쪽 기슭에 있는 사마리아의 작은 마을인 아스카르로 확인되었습니다.","source_sha256":"c1bbb13d3baeb09943936b87629896e686975c335a63e6e23dbd29712a6f7e1c","citation_candidates":[{"source":"Isa. 28:1","passage":"isa-28","verse":1,"ref":"isa-28:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"John 4:5","passage":"jhn-4","verse":5,"ref":"jhn-4:5","status":"KRV_VERIFIED","exact_korean_token":"수가"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0085","name_en":"Tabor","name_ko":"다볼","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-TABOR","ko":"소구. 타보르 A 높이. (1.) 이제 갈릴리 바다에서 서쪽으로 11마일 떨어진 곳에 원뿔 모양의 눈에 띄는 산인 Jebel et-Tur가 있습니다. 높이는 약 1,843피트입니다. 정상에서 바라보는 경치는 유난히 넓고 웅장하다고 한다. 이것은 Ps. 89:12; Jer. 46:18. 바락이 시스라(q.v.) 사사와의 전투 전에 진을 쳤던 곳이 바로 이곳이었습니다. 4:6-14. 그러나 근거 없는 오래된 전승이 있는데, 그곳이 우리 주님의 변형된 장면이었다는 것입니다. (헤르몬 참조) “북쪽 부족과 남쪽 부족 사이, 산맥과 중앙 평야 사이의 국경 지대에 서 있는 다볼의 탁월함과 고립으로 인해 그곳은 모든 시대에 주목받는 장소가 되었으며, 시편 필자는 그곳을 남쪽과 북쪽을 상징하는 헤르몬과 연관시키게 된 것 같습니다.” 아직도 이것이였다고 주장하는 사람들이 있다. 변형의 장면(q.v.). (2.) 스불룸의 성읍(대상 6:77). (3.) “다볼 평지”(삼상 10:3)는 개정판에서와 같이 “다볼 상수리나무”여야 합니다. 이것은 아마도 창 35:8의 알론바굿이었을 것이다.","source_sha256":"689f490411cccad95dacf8dab43e12a86db0d4b09b888bb249b360632c5580a2","citation_candidates":[{"source":"Ps. 89:12","passage":"psa-89","verse":12,"ref":"psa-89:12","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"Jer. 46:18","passage":"jer-46","verse":18,"ref":"jer-46:18","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"Judg. 4:6-14","passage":"jdg-4","verse":6,"ref":"jdg-4:6","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"1 Chr. 6:77","passage":"1ch-6","verse":77,"ref":"1ch-6:77","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"1 Sam. 10:3","passage":"1sa-10","verse":3,"ref":"1sa-10:3","status":"KRV_VERIFIED","exact_korean_token":"다볼"},{"source":"Gen. 35:8","passage":"gen-35","verse":8,"ref":"gen-35:8","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0087","name_en":"Tarsus","name_ko":"다소","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-TARSUS","ko":"족근. 타르수스 길리기아의 주요 도시. 그것은 부와 학문 학교로 유명했고, 아테네와 알렉산드리아와도 경쟁할 수 있었습니다. 아니, 뛰어났으며, 따라서 \"천박하지 않은 도시\"라고 불렸습니다. 이곳은 사도 바울이 태어난 곳이다(행 21:39). 그것은 지중해에서 북쪽으로 약 12마일 떨어진 키드누스 강둑에 서 있었습니다. 아시리아 왕 사르다나팔루스(Sardanapalus)가 창건했다고 전해진다. 지금은 테르수스(Tersous)라고 불리는 더럽고 파멸적인 터키 마을이 되었습니다. (폴 참조)","source_sha256":"649d9495b0c87c1560f38019edffc71fa5bb92304df314ed10637a20c8d6d471","citation_candidates":[{"source":"Acts 21:39","passage":"act-21","verse":39,"ref":"act-21:39","status":"KRV_VERIFIED","exact_korean_token":"다소"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0088","name_en":"Thessalonica","name_ko":"데살로니가","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-THESSALONICA","ko":"데살로니가. 데살로니가 Thermaic 만에 위치한 크고 인구가 많은 도시. 이곳은 마케도니아의 로마 4개 지역 중 하나의 수도였으며 법무관의 통치를 받았습니다. 이 도시를 건설한 가산더의 아내 데살로니가의 이름을 따서 명명되었습니다. 그녀의 아버지 빌립은 그녀를 그렇게 불렀습니다. 왜냐하면 빌립이 테살리아 사람들에게 승리를 거둔 날 그녀가 태어났다는 소식을 처음 들었기 때문입니다. 바울은 2차 전도 여행에서 마케도니아 지방에 있는 유대인의 주요 회당인 이곳 회당에서 설교하고 교회의 기초를 놓았습니다(행 17:1-4, 살전 1:9). 유대인들의 폭력으로 인해 그는 베뢰아로 도망할 때 그 도시에서 쫓겨났습니다(행 17:5-10). 바울과 실라가 함께 묵었던 유대인들이 “야손을 모은” “그 성의 통치자들”은 원문에는 폴리타르카이(politarchai)라고 불리는 특이한 단어로 되어 있지만, 데살로니카의 한 아치에서. 이 발견은 역사가의 정확성을 확인시켜줍니다. 바울은 이후에 이곳 교회를 방문했습니다(20:1-3). 이 도시는 오랫동안 그 중요성을 유지해 왔습니다. 살로니키(Saloniki)라는 이름으로 약 85,000명의 인구가 혼합되어 있는 유럽 터키의 가장 중요한 도시입니다.","source_sha256":"ffc976614ed0bfb21292eb515b6cb9c2862fa93f55e5ea21277541327d7fbc88","citation_candidates":[{"source":"Acts 17:1-4","passage":"act-17","verse":1,"ref":"act-17:1","status":"KRV_VERIFIED","exact_korean_token":"데살로니가"},{"source":"Acts 17:5-10","passage":"act-17","verse":5,"ref":"act-17:5","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0089","name_en":"Thyatira","name_ko":"두아디라","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-THYATIRA","ko":"두아디라. 두아디라 소아시아의 도시로 루디아와 무시아 국경에 위치해 있다. 그것의 현대 이름은 Ak-hissar, 즉 “하얀 성”입니다. 여기에는 일곱 교회 ​​중 하나가 있었습니다(계 1:11; 2:18-28). 자주빛 옷감 곧 이 색으로 물들인 옷감을 파는 루디아도 이 성읍 사람이었더라(행 16:14) 염색으로 유명했고 지금도 유명해요. 유적 중에는 고대 그 도시의 염색공 길드와 관련된 비문이 발견되었습니다.","source_sha256":"68667fdfb871706fb156d43bd39ad071eea08868519ae95a1d577f8ca2db21e1","citation_candidates":[{"source":"Rev. 1:11","passage":"rev-1","verse":11,"ref":"rev-1:11","status":"KRV_VERIFIED","exact_korean_token":"두아디라"},{"source":"Acts 16:14","passage":"act-16","verse":14,"ref":"act-16:14","status":"KRV_VERIFIED","exact_korean_token":"두아디라"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0091","name_en":"Troas","name_ko":"드로아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-TROAS","ko":"트로아스. 트로아스 소아시아 북서쪽에 있는 무시아 해안에 있는 도시로, 북쪽으로 약 4마일 떨어진 고대 트로이아의 이름을 따서 명명되었습니다. 여기서 바울은 2차 선교 여행 중에 “마게도냐 사람”이 나타나 “와서 우리를 도우라”(행 16:8-11) 하는 환상을 보았습니다. 그는 다른 경우에도 이 장소를 방문했는데, 이번 방문 중 한 번은 옷과 책 몇 권을 그곳에 두고 왔습니다(고후 2:12; 딤후 4:13). 트로아스의 폐허는 수 마일에 걸쳐 뻗어 있으며, 현재 그 부지는 대부분 참나무 숲으로 덮여 있습니다. 유적의 현대 이름은 Eski Stamboul, 즉 Old Constantinople입니다.","source_sha256":"14abf6d749e0b4548b8180e2d1965e6fb89d27d26127dea3349b3830eeef07cd","citation_candidates":[{"source":"Acts 16:8-11","passage":"act-16","verse":8,"ref":"act-16:8","status":"KRV_VERIFIED","exact_korean_token":"드로아"},{"source":"2 Cor. 2:12","passage":"2co-2","verse":12,"ref":"2co-2:12","status":"KRV_VERIFIED","exact_korean_token":"드로아"},{"source":"2 Tim. 4:13","passage":"2ti-4","verse":13,"ref":"2ti-4:13","status":"KRV_VERIFIED","exact_korean_token":"드로아"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0092","name_en":"Ur","name_ko":"우르","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-UR","ko":"우르. 우르 빛(Ur Light) 또는 달의 도시, “갈대아인의” 도시, 하란의 탄생지(창 11:28,31), 시날 또는 갈대아 북부의 가장 큰 도시, 국가의 주요 상업 중심지이자 정치 권력의 중심지. 그것은 서쪽 제방의 유프라테스 강 어귀 근처에 서 있었고, 엘 무게이르(역청으로 시멘트를 붙인 벽돌)의 둔덕, 즉 “역청” 또는 “역청 마을”로 대표됩니다. 이곳은 현재 바다에서 150마일, 유프라테스에서 약 6마일 떨어져 있으며, 티그리스 강의 풍요로운 산인 샤트엘히에 강을 받아들이는 지점보다 조금 더 높습니다. 페르시아 만의 물이 지금까지 내륙까지 닿았기 때문에 이곳은 이전에는 해상 도시였습니다. 우르는 바빌로니아의 항구였으며, 그곳에서 만 연안의 주민들과 인도, 에티오피아, 이집트 등 먼 나라들과 교역이 이루어졌습니다. 대략 버려졌는데 기원전 500개였으나 그곳에서 발견된 무덤의 수에서 알 수 있듯이 에렉처럼 오랫동안 계속해서 거대한 신성한 묘지 도시였습니다. (아브라함 참조) 우리에게 알려진 우르의 가장 오래된 왕은 우르바우(바우 여신의 종)(홈멜이 이름을 읽음)이고, 우르구르(다른 사람들이 읽음)입니다. 그는 기원전 2,800년쯤 살았고, 우르에 달의 신 신(Sin)의 유명한 신전을 짓는 데 참여했습니다. 여기에 제시된 그림은 수메르어로 쓰여 우르 신전의 모든 벽돌에 새겨진 그의 설형 문자 비문을 나타냅니다. “달신의 신전을 지은 우르의 왕 우르바우”라고 적혀 있습니다. \"우르는 바빌로니아의 달신인 신을 숭배하는 데 봉헌되었습니다. 그러나 이 영광은 다른 도시와 공유했는데 이 도시는 하란 또는 하란이었습니다. 하란은 메소포타미아에 있었고, 그 이름은 메소포타미아에 있었고, 그 이름은 그것을 통해 동쪽에서 서쪽으로. 그 이름은 바빌로니아이며 바빌로니아 왕이 이곳을 세웠음을 증거합니다. 동일한 증거가 바벨론의 달신과 고대 신(Sin) 신전에 바쳐진 예배를 통해 훨씬 더 결정적으로 입증됩니다. 실제로 하란에 있는 달신의 신전은 아마도 우르에 있는 달신의 신전보다 아시리아와 바빌로니아 세계에서 훨씬 더 유명했을 것입니다. \"결과적으로 우르와 하란 사이에는 초기에 밀접한 관계가 있었음에 틀림없으며 이에 대한 기록은 아직 회복되지 않았습니다. 하란은 우르의 왕에게 그 기초를 세웠을 수도 있습니다. 어쨌든 두 도시는 동일한 신에 대한 숭배로 서로 묶여 있었는데, 이는 고대 세계에 존재했던 가장 가깝고 가장 지속적인 결합의 유대였습니다. 그러므로 데라가 우르에서 하란으로 이주했어야 했다는 주장은 더 이상 불가능합니다. 기이한. 그가 우르를 떠난다면 그곳이 가장 자연스럽게 갈 수 있는 곳이었습니다. 그것은 마치 성전의 한 뜰에서 다른 뜰로 넘어가는 것과 같았습니다. \"성서의 이야기와 고고학 연구의 증거 사이의 놀라운 일치는 우연의 결과일 수 없습니다. 이야기는 역사적이어야 합니다. 비록 그가 바빌로니아 사람이라 할지라도 최근의 어떤 작가도 우리가 현재 진실이라고 알고 있는 것과 정확히 일치하는 이야기를 만들어낼 수 없었을 것입니다. 팔레스타인 전통이 발명한 종류의 이야기도 똑같이 불가능하기 때문입니다. 편견이 없는 사람에게는 데라가 우르에서 우르로 이주한 역사가 있다는 결론에서 벗어날 수 없습니다. Harran은 사실에 기초를 두고 있습니다.”(Sayce)","source_sha256":"dc4b9e2ccdbb91fa5aeef4a8b49db0b422a49563b0acdd1357a6176c2253f29f","citation_candidates":[{"source":"Gen. 11:28","passage":"gen-11","verse":28,"ref":"gen-11:28","status":"KRV_VERIFIED","exact_korean_token":"우르"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0093","name_en":"Zarephath","name_ko":"사르밧","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ZAREPHATH","ko":"사르밧. Zarephath Smelting-shop, \"금속 제련 및 제련을 위한 작업장\", 페니키아의 작은 마을(현재 Surafend)은 해안에서 약 1마일, 티레와 시돈 사이 도로의 거의 중간 지점에 있습니다. 이곳에서 엘리야는 “하늘이 삼년 육개월간 닫히는” “큰 기근” 동안 가난한 과부와 함께 머물렀습니다(누가복음 4:26; 열왕기상 17:10). 신약성경에서는 사렙타라고 불린다(눅 4:26).","source_sha256":"bcd0921cbe6d85fcf8ab389ace532518882854e7b7c8b1782aad6de338c58947","citation_candidates":[{"source":"Luke 4:26","passage":"luk-4","verse":26,"ref":"luk-4:26","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Kings 17:10","passage":"1ki-17","verse":10,"ref":"1ki-17:10","status":"KRV_VERIFIED","exact_korean_token":"사르밧"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0094","name_en":"Ziklag","name_ko":"시글락","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ZIKLAG","ko":"시글락. 시글락 다윗이 모든 추종자들과 함께 십에서 가드로 도망쳤을 때 블레셋 사람들의 소유였던 네게브 또는 유다 남쪽 나라(수 15:31)에 있는 성읍. 아기스 왕은 그에게 시글락을 거주지로 지정했습니다. 그곳에서 그는 1년 4개월 넘게 살았습니다. 이때부터 그것은 유다 왕들에게 속하였다(삼상 27:6). 이스라엘 사람들을 치려는 블레셋 원정에 합류하기 위해 그의 군대와 함께 부재하는 동안(29:11), 그 곳은 아말렉 사람들에 의해 멸망되었습니다(30:1, 2). 그러나 다윗은 그들을 추격하여 완전히 패주시키고 모든 포로들을 돌려보냈습니다(삼상 30:26-31). 이 원정에서 돌아온 지 이틀 후, 다윗은 길보아에서 벌어진 참혹한 전투와 사울의 죽음에 대한 소식을 받았습니다(삼하 1:1-16). 이제 그는 그의 두 아내 아히노암과 아비가일과 그의 부대 600명과 함께 시글락을 떠나 헤브론으로 돌아왔다. 남자들. 그것은 브엘세바 남쪽의 유적 더미인 '아슬루즈'로 확인되었습니다. 그러나 Conder는 그것을 블레셋과 유다와 아말렉의 경계에 있는 브엘세바에서 북서쪽으로 약 17마일 떨어진 0.5마일 떨어진 세 개의 언덕에서 발견된 폐허인 키르베트 주헤일리카와 동일시합니다.","source_sha256":"de26e3075e7dacda4159cec6cd44d8255cb1966a9b4dc74b43b9081fbb8b70ea","citation_candidates":[{"source":"Josh. 15:31","passage":"jos-15","verse":31,"ref":"jos-15:31","status":"KRV_VERIFIED","exact_korean_token":"시글락"},{"source":"1 Sam. 27:6","passage":"1sa-27","verse":6,"ref":"1sa-27:6","status":"KRV_VERIFIED","exact_korean_token":"시글락"},{"source":"1 Sam. 30:26-31","passage":"1sa-30","verse":26,"ref":"1sa-30:26","status":"KRV_VERIFIED","exact_korean_token":"시글락"},{"source":"2 Sam. 1:1-16","passage":"2sa-1","verse":1,"ref":"2sa-1:1","status":"KRV_VERIFIED","exact_korean_token":"시글락"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0095","name_en":"Zoar","name_ko":"소알","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ZOAR","ko":"조알. 롯과 그의 딸들이 소돔에서 도망했던 사해의 동쪽 또는 남동쪽에 있는 마을인 소알 스몰(창 19:22, 23). 원래는 벨라라고 불렸습니다(14:2, 8). 이사야 선지자(15:5)와 예레미야 선지자(48:34)가 이를 언급합니다. 그 폐허는 열왕기하 3장에 언급된 키르모압, 현대의 텔에쉬샤구르인 케락 계곡의 입구에서 아직도 볼 수 있습니다.","source_sha256":"44114bddd58531cdc9de7e879664c7fed92928f8c3fdfbda10edf5acb1c9f651","citation_candidates":[{"source":"Gen. 19:22","passage":"gen-19","verse":22,"ref":"gen-19:22","status":"KRV_VERIFIED","exact_korean_token":"소알"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0098","name_en":"Adullam","name_ko":"아둘람","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-ADULLAM","ko":"아둘람. 아둘람 가나안 사람들의 왕도 중 하나, 현재는 '아이델마'(수 12:15; 15:35). 그 곳은 다윗이 골리앗을 상대로 기억에 남는 승리를 거두었던(삼상 17:2) 장면이었으며 가드에서 멀지 않은 엘라 계곡(q.v.)의 옛 로마 도로에 서 있었습니다. 이곳은 르호보암이 애굽에 맞서 요새화한 성읍 중 하나였습니다(대하 11:7). 그것은 “이스라엘의 영광”(미가 1:15)이라고 불렸습니다. 아둘람 동굴은 다윗이 승리한 곳에서 남쪽으로 약 2마일, 베들레헴에서 서쪽으로 약 13마일 떨어진 곳에서 발견되었습니다. 이 곳에는 수많은 동굴이 뚫린 약 500피트 높이의 언덕이 있는데, 그 중 하나에 다윗은 “환난 당한 모든 자와 빚진 자와 마음이 원통한 모든 자를” 모았습니다(삼상 22:2). 이 동굴 중 일부는 200~300명을 수용할 수 있을 만큼 충분히 큽니다. 전통에 따르면 이 동굴은 베들레헴과 사해 사이의 와디 쿠레이툰(Wady Khureitun)에 있지만 이 견해는 잘 유지될 수 없습니다.","source_sha256":"14a632595a415711f7b2f0c7153ab9631547d2809f178f6138abb0e2806e2487","citation_candidates":[{"source":"Josh. 12:15","passage":"jos-12","verse":15,"ref":"jos-12:15","status":"KRV_VERIFIED","exact_korean_token":"아둘람"},{"source":"1 Sam. 17:2","passage":"1sa-17","verse":2,"ref":"1sa-17:2","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Chr. 11:7","passage":"2ch-11","verse":7,"ref":"2ch-11:7","status":"KRV_VERIFIED","exact_korean_token":"아둘람"},{"source":"Micah 1:15","status":"UNSUPPORTED_BOOK"},{"source":"1 Sam. 22:2","passage":"1sa-22","verse":2,"ref":"1sa-22:2","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0099","name_en":"Aenon","name_ko":"애논","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-AENON","ko":"AE논. AEnon Springs, 요한이 세례를 주었던 살림 근처의 장소(요한복음 3:23). 그곳은 아마도 에발 산에서 요르단까지 뻗어 있는 탁 트인 계곡인 와디 파라의 상류 수원 근처에 있었을 것입니다. 샘이 가득합니다. 샘에서 북쪽으로 4마일 떨어진 곳에 '아이눈'이라는 곳이 발견되었습니다.","source_sha256":"8aeed89bdf7b25b4ac271f5e4083236b2cb737855fb216d84c6a882306412788","citation_candidates":[{"source":"John 3:23","passage":"jhn-3","verse":23,"ref":"jhn-3:23","status":"KRV_VERIFIED","exact_korean_token":"애논"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0100","name_en":"Aroer","name_ko":"아로엘","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-AROER","ko":"아로에르. 아로에르 유적. (1) 시혼 왕국(수 12:2)의 남쪽 경계인 아르논 강 북쪽 기슭에 있는 성읍(신명 4:48; 삿 11:26; 왕하 10:33). 현재는 사해에서 서쪽으로 13마일 떨어진 아라이르(Arair)라고 불립니다. (2.) 갓 지파(민 32:34)가 암몬의 수도인 “랍바 앞”(수 13:25)에 건설한 성읍들 중 하나. 이것은 입다의 역사(삿 11:33)와 다윗의 역사(삼하 24:5)에서 유명했습니다. (비교 사 17:2; 왕하 15:29.) (3.) 다윗이 시글락에 있는 아말렉 사람들에게서 전리품을 되찾은 후 브엘세바에서 남동쪽으로 19킬로미터 떨어진 유다 남쪽에 있는 도시(삼상 30:26, 28). 이곳은 다윗의 두 용사가 태어난 도시였습니다(대상 11:44). 지금은 아라라(Ar'arah)라고 불립니다.","source_sha256":"d87291330e61442ae4da71ff988075ef9ae1613aeddf59480c4943928fbcd158","citation_candidates":[{"source":"Deut. 4:48","passage":"deu-4","verse":48,"ref":"deu-4:48","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Judg. 11:26","passage":"jdg-11","verse":26,"ref":"jdg-11:26","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"2 Kings 10:33","passage":"2ki-10","verse":33,"ref":"2ki-10:33","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Josh. 12:2","passage":"jos-12","verse":2,"ref":"jos-12:2","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Num. 32:34","passage":"num-32","verse":34,"ref":"num-32:34","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Josh. 13:25","passage":"jos-13","verse":25,"ref":"jos-13:25","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Judg. 11:33","passage":"jdg-11","verse":33,"ref":"jdg-11:33","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"2 Sam. 24:5","passage":"2sa-24","verse":5,"ref":"2sa-24:5","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"Isa. 17:2","passage":"isa-17","verse":2,"ref":"isa-17:2","status":"KRV_VERIFIED","exact_korean_token":"아로엘"},{"source":"2 Kings 15:29","passage":"2ki-15","verse":29,"ref":"2ki-15:29","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 30:26","passage":"1sa-30","verse":26,"ref":"1sa-30:26","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Chr. 11:44","passage":"1ch-11","verse":44,"ref":"1ch-11:44","status":"KRV_VERIFIED","exact_korean_token":"아로엘"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0101","name_en":"Bethphage","name_ko":"벳바게","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BETH-PHAGE","ko":"베스파지. 익지 않은 무화과나무가 사는 벳바게의 집. 예루살렘에서 여리고로 가는 길에 있는 감람산 위의 마을(마 21:1; 막 11:1; 눅 19:29), 베다니와 매우 가까운 집. 그것은 예루살렘에서 안식일 여행의 한계, 즉 2,000큐빗이었다. 그것은 현대의 Kefr-et-Tur로 확인되었습니다.","source_sha256":"7703902376b33a19f3f8769f38d54e6a1fb43012e064e0bb1969b34f5f2a06b3","citation_candidates":[{"source":"Matt. 21:1","passage":"mat-21","verse":1,"ref":"mat-21:1","status":"KRV_VERIFIED","exact_korean_token":"벳바게"},{"source":"Mark 11:1","passage":"mrk-11","verse":1,"ref":"mrk-11:1","status":"KRV_VERIFIED","exact_korean_token":"벳바게"},{"source":"Luke 19:29","passage":"luk-19","verse":29,"ref":"luk-19:29","status":"KRV_VERIFIED","exact_korean_token":"벳바게"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0102","name_en":"Berea","name_ko":"베뢰아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BEREA","ko":"베레아. 베뢰아 바울이 데살로니가에서 박해를 받았을 때 실라와 디모데와 함께 갔던 마케도니아의 도시(행 17:10, 13), 또한 그가 해변으로 도피한 후 배를 타고 아테네로 갔을 때 그곳을 떠나지 않을 수 없었다(14, 15). 바울의 동료 중 한 사람인 소바더도 이 도시에 속해 있었는데, 아마도 그의 회심은 이때 일어났을 것입니다(행 20:4). 지금은 베리아(Verria)라고 불립니다.","source_sha256":"2b69fc9701197b07f1e0d9528357fd0ca6eda1b1f200c1bf86b536cd5d815694","citation_candidates":[{"source":"Acts 17:10","passage":"act-17","verse":10,"ref":"act-17:10","status":"KRV_VERIFIED","exact_korean_token":"베뢰아"},{"source":"Acts 20:4","passage":"act-20","verse":4,"ref":"act-20:4","status":"KRV_VERIFIED","exact_korean_token":"베뢰아"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0103","name_en":"Bithynia","name_ko":"비두니아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-BITHYNIA","ko":"비티니아. 비티니아(Bithynia) 소아시아의 유신(Euxine) 강과 프로폰티스(Propontis) 강 남쪽에 있는 지방. 이곳에서는 초기에 그리스도인 회중이 형성되었습니다(베드로전서 1:1). 바울은 성령에 의해 이 지방에 들어가지 못하게 되었습니다(행 16:7). 교회 역사에는 로마 총독으로서 플리니우스가 다스린 속주로 기록되어 있습니다. 그는 기독교 신앙 고백과 행위로 인해 자신의 법정에 끌려온 수많은 그리스도인들을 어떻게 처리해야 할지 고민하고 황제 트라야누스에게 지시를 위해 편지를 썼습니다(A.D. 107).","source_sha256":"e6e1c15902a1cb2bb8635447d5befe989faf3a353ac30b8e49d8786c6fa2a2fe","citation_candidates":[{"source":"1 Pet. 1:1","passage":"1pe-1","verse":1,"ref":"1pe-1:1","status":"KRV_VERIFIED","exact_korean_token":"비두니아"},{"source":"Acts 16:7","passage":"act-16","verse":7,"ref":"act-16:7","status":"KRV_VERIFIED","exact_korean_token":"비두니아"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0106","name_en":"Dor","name_ko":"돌","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-DOR","ko":"도르. 도르 거주지, 로마인의 도라, 가나안 사람들의 고대 왕도(수 11:1, 2; 12:23). 이곳은 시리아 해안에 있는 페니키아인의 최남단 정착지였습니다. 원래 주민들은 다윗에 의해 속국이 되었지만 결코 추방된 적이 없는 것 같습니다. 이곳은 솔로몬의 위원회 구역 중 하나였습니다(삿 1:27; 왕상 4:11). 그것은 탄투라(그 탑이 탄투르, 즉 “뿔”과 닮았다고 해서 그렇게 명명되었습니다)와 동일시되었습니다. 이 탑은 1895년에 무너졌고, 옛 십자군 요새의 유적인 잔해와 기초 벽 외에는 아무것도 남지 않았습니다. 그곳은 가이사랴에서 북쪽으로 약 8마일 떨어진 곳에 있는 “벌거벗은 해변에 있는 비참하고 병든 오두막집”이었습니다.","source_sha256":"19b00d8b7c4474cdddc856f7af00174aa5bb059189a83f8ededc5f627c7cf372","citation_candidates":[{"source":"Josh. 11:1","passage":"jos-11","verse":1,"ref":"jos-11:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Judg. 1:27","passage":"jdg-1","verse":27,"ref":"jdg-1:27","status":"KRV_VERIFIED","exact_korean_token":"돌"},{"source":"1 Kings 4:11","passage":"1ki-4","verse":11,"ref":"1ki-4:11","status":"KRV_VERIFIED","exact_korean_token":"돌"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0107","name_en":"Ebal","name_ko":"에발","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-EBAL","ko":"에발. 에발 스토니. (1.) 해수면에서 3,076피트, 계곡에서 1,200피트 높이에 있는 산으로, 그 북쪽에는 세겜 성읍이 서 있었다(q.v.). 이 산에서는 여섯 지파(신 27:12,13)가 서서 레위인들이 율법을 낭독하는 골짜기에서 발한 저주에 규정된 형식에 따라 응답하도록 임명되었다(11:29; 29:4, 13). 이 산은 또한 여호와를 위해 세워진 최초의 큰 제단이 있던 곳이기도 합니다(신명 27:5-8; 수 8:30-35). 그 이후로 에발이라는 이름은 유대 역사에 다시는 나타나지 않습니다. (게리심 참조) (2.) 오발이라고도 불리는 에벨의 후손(대상 1:22)(창 10:28). (3) 호리 사람 세일의 후손(창 36:23).","source_sha256":"d39f8cdc4f65be6598f60d881b95e2f30d251308e5e98d28c7bd677ef32b0e5a","citation_candidates":[{"source":"Deut. 27:12","passage":"deu-27","verse":12,"ref":"deu-27:12","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Deut. 27:5-8","passage":"deu-27","verse":5,"ref":"deu-27:5","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Josh. 8:30-35","passage":"jos-8","verse":30,"ref":"jos-8:30","status":"KRV_VERIFIED","exact_korean_token":"에발"},{"source":"1 Chr. 1:22","passage":"1ch-1","verse":22,"ref":"1ch-1:22","status":"KRV_VERIFIED","exact_korean_token":"에발"},{"source":"Gen. 10:28","passage":"gen-10","verse":28,"ref":"gen-10:28","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Gen. 36:23","passage":"gen-36","verse":23,"ref":"gen-36:23","status":"KRV_VERIFIED","exact_korean_token":"에발"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0110","name_en":"Geba","name_ko":"게바","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-GEBA","ko":"게바. 게바 기브아 근처 유다 북쪽 경계에 있는 언덕,(삼하 5:25[대상 14:16, “기브온”]; 왕하 23:8; 느 11:31) 베냐민의 레위 도시(열왕기상 15:22; 삼상 13:16; 14:5, A.V.에서는 “기브아”로 잘못 표기됨) (이사야 10:29; 여호수아 18:24, 28) “게바에서 브엘세바까지”가 유다 왕국의 전체 범위를 표현한 것처럼, “단부터 브엘세바까지”가 팔레스타인 전체 지역을 묘사한 것과 같습니다(왕하 23:8). 그곳은 예루살렘에서 북쪽으로 약 5 1/2마일 떨어진 곳에 있는 가바(수 18:24; 에스라 2:26; 느 7:30), 현재는 예바와 동일시됩니다.","source_sha256":"4ef5bd9c1cfd5ee9565345f5d1f99b4fefffb1805d4f4ce418e7922394889d97","citation_candidates":[{"source":"2 Sam. 5:25","passage":"2sa-5","verse":25,"ref":"2sa-5:25","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"1 Chr. 14:16","passage":"1ch-14","verse":16,"ref":"1ch-14:16","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Kings 23:8","passage":"2ki-23","verse":8,"ref":"2ki-23:8","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Neh. 11:31","passage":"neh-11","verse":31,"ref":"neh-11:31","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"1 Kings 15:22","passage":"1ki-15","verse":22,"ref":"1ki-15:22","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"1 Sam. 13:16","passage":"1sa-13","verse":16,"ref":"1sa-13:16","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Isa. 10:29","passage":"isa-10","verse":29,"ref":"isa-10:29","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Josh. 18:24","passage":"jos-18","verse":24,"ref":"jos-18:24","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Ezra 2:26","passage":"ezr-2","verse":26,"ref":"ezr-2:26","status":"KRV_VERIFIED","exact_korean_token":"게바"},{"source":"Neh. 7:30","passage":"neh-7","verse":30,"ref":"neh-7:30","status":"KRV_VERIFIED","exact_korean_token":"게바"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0114","name_en":"Makkedah","name_ko":"막게다","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MAKKEDAH","ko":"막게다. 가나안 사람들의 왕도 중 하나인 막게다 목자의 장소(수 12:16). 그 근처에는 이스라엘을 대항하여 연합한 다섯 왕이 피난처를 찾았던 동굴이 있었다(10:10-29). 그들은 여호수아에 의해 죽임을 당했고, 그 후 다섯 그루의 나무에 그들의 몸을 매달았습니다. 이곳은 고대 유적과 거대한 동굴이 있는 Eleutheropolis(Beit Jibrin) 북서쪽으로 약 7마일 떨어진 낮은 언덕에 서 있는 Sumeil이라는 현대 마을과 동일시되었습니다. 그러나 팔레스타인 탐험 측량자들은 이곳이 야브네에서 3마일 떨어져 있고 에크론에서 남서쪽으로 2 1/2 떨어진 엘 무가르 즉 “동굴”로 확인했습니다. 왜냐하면 그들은 “팔레스타인 평야에 있는 막케다의 가능한 모든 유적지 중 이 유적지에만 아직도 동굴이 존재”하기 때문이라고 말합니다. (아도니세덱 참조)","source_sha256":"3c1fc8ee232b837ea0997badc7457488177704562b173f964df048a02f588e1a","citation_candidates":[{"source":"Josh. 12:16","passage":"jos-12","verse":16,"ref":"jos-12:16","status":"KRV_VERIFIED","exact_korean_token":"막게다"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0116","name_en":"Moriah","name_ko":"모리아","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-MORIAH","ko":"모리아. 모리아 여호와의 택하신 자. 어떤 사람들은 그리심 산을 의미한다고 주장하지만, 아마도 우리는 이 산을 예루살렘 언덕 중 하나로 간주할 것입니다. 솔로몬의 성전은 여부스 사람 오르난의 타작마당이었던 곳에 세워졌습니다(삼하 24:24, 25; 대하 3:1). 이곳은 대개 시온에 속하며 북동쪽에 위치하며 티로포아 계곡을 사이에 두고 분리되어 있습니다. 이곳은 아브라함이 아들 이삭을 바치러 갔던 “모리아 땅”이었습니다(창 22:2). 현재 모하메드의 쿠베테스-사크라(바위 돔)로 덮여 있는 사원 언덕의 가장 높은 지점이 아라우나의 타작 마당이 있었던 실제 장소인 것으로 추정되어 왔습니다. 아브라함이 있은 지 천년이 지난 이곳에서도 다윗은 제단을 쌓고 하나님께 제사를 드렸습니다. (예루살렘; 인구 수 계산 참조)","source_sha256":"3f7ebc7588a5d125a5a1d0d3d8f2b3103078fec64bdf30c92a91c8f11d4b414e","citation_candidates":[{"source":"2 Sam. 24:24","passage":"2sa-24","verse":24,"ref":"2sa-24:24","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Chr. 3:1","passage":"2ch-3","verse":1,"ref":"2ch-3:1","status":"KRV_VERIFIED","exact_korean_token":"모리아"},{"source":"Gen. 22:2","passage":"gen-22","verse":2,"ref":"gen-22:2","status":"KRV_VERIFIED","exact_korean_token":"모리아"}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0117","name_en":"Nob","name_ko":"놉","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-NOB","ko":"귀족. 놉산당, 제사장들의 성읍. 다윗의 방황의 역사에서 처음으로 언급되었다(삼상 21:1). 당시 여기에 성막이 서 있었고 제사장 아히멜렉도 여기에 거주하고 있었습니다. (아히멜렉 참조) 10:28-32 예루살렘 근처에 있었던 것 같다. 일부 사람들은 이곳이 예루살렘 북동쪽으로 1마일 반 떨어진 ​​엘 이사위예(el-Isawiyeh)에 있는 것으로 확인했습니다. 하지만 Isa에 따르면. 10:28-32 그곳은 게바 남쪽에 있었고, 예루살렘으로 가는 길에 있었고, 그 성이 보이는 곳에 있었다. 이러한 동일성은 이러한 조건을 충족시키지 못하므로 다른 사람들(딘 스탠리)은 그곳이 다윗이 압살롬을 피해 도망할 때 “하나님을 경배”한 곳인 감람산 북쪽 정상이었다고 생각하거나(삼하 15:32), 아마도(콘더) 그곳이 미스베(q.v.), Judg. 20:1; 조롱. 18:26; 1 샘. 7시 16분, 북서쪽으로 약 5마일 떨어진 Nebi Samwil에서 예루살렘. 다윗은 거룩한 진설병을 받고 에봇 뒤에서 가져온 골리앗의 칼을 차고 놉에서 도망하여 가드 왕 아기스의 뜰로 피신하여 그곳에서 감옥에 갇혔습니다. (시 34편과 56편의 제목을 비교하라.)","source_sha256":"83acc41e03714316472aa654ec67481a6fa998656f7d79e1cdb867eb8ed0f358","citation_candidates":[{"source":"1 Sam. 21:1","passage":"1sa-21","verse":1,"ref":"1sa-21:1","status":"KRV_VERIFIED","exact_korean_token":"놉"},{"source":"Isa. 10:28-32","passage":"isa-10","verse":28,"ref":"isa-10:28","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"2 Sam. 15:32","passage":"2sa-15","verse":32,"ref":"2sa-15:32","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Judg. 20:1","passage":"jdg-20","verse":1,"ref":"jdg-20:1","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"Josh. 18:26","passage":"jos-18","verse":26,"ref":"jos-18:26","status":"KRV_VERIFIED","exact_korean_token":null},{"source":"1 Sam. 7:16","passage":"1sa-7","verse":16,"ref":"1sa-7:16","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0118","name_en":"Ophel","name_ko":"오벨","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-OPHEL","ko":"오펠. 오펠힐; 둔덕, 두로포에온과 기드론 계곡 사이에 있는 성전 언덕의 남쪽 경사면에 있는 길고 좁고 둥근 곶(대하 27:3; 33:14; 느 3:26, 27). 그곳은 별도의 성벽으로 둘러싸여 있었으며 포로 생활 이후에는 느디님 사람들이 차지했습니다. 이 벽은 팔레스타인 탐사 기금의 기술자들이 성전 지역의 남동쪽 각도에서 발견했습니다. 현재 표면에서 4피트 아래에 있습니다. 열왕기하 5장 24절에서 이 단어는 “망대”(R.V., “언덕”)로 번역되었는데, 이는 아마도 엘리사의 집 근처에 있는 어떤 높은 곳을 의미하는 것 같습니다.","source_sha256":"a4bacab73c1d9914964f0ebfceba24755e04fd75bbe68900bae3dfb731d0291e","citation_candidates":[{"source":"2 Chr. 27:3","passage":"2ch-27","verse":3,"ref":"2ch-27:3","status":"KRV_VERIFIED","exact_korean_token":"오벨"},{"source":"Neh. 3:26","passage":"neh-3","verse":26,"ref":"neh-3:26","status":"KRV_VERIFIED","exact_korean_token":"오벨"},{"source":"2 Kings 5:24","passage":"2ki-5","verse":24,"ref":"2ki-5:24","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"},{"candidate_id":"ATLBC-CAND-0121","name_en":"Shunem","name_ko":"수넴","title_status":"EDITORIAL_DRAFT_NOT_PROFESSIONALLY_APPROVED","source_id":"k-SHUNEM","ko":"수넴. 수넴 이스르엘 북쪽과 길보아 산 남쪽에 있는 잇사갈 지파의 작은 마을인 두 개의 안식처(수 19:18). 이곳에는 블레셋 사람들이 사울을 공격하러 왔을 때 진을 쳤고(삼상 28:4), 엘리사가 그곳의 부유한 여인의 환대를 받았던 곳이다. 이 여자의 아들이 갑작스럽게 죽자 그 여자는 엘리사에게 알리고 그를 수넴으로 데려가려고 평지 건너편 20마일 떨어진 갈멜로 급히 달려갔습니다. 그곳 “선지자의 방”에는 죽은 아이가 누워 있었습니다. 엘리사가 거기 들어가서 문을 닫고 간절히 기도하니 아이가 살아나더라(왕하 4:8-37) 이 여자는 나중에 기근 중에 블레셋 사람들의 저지대로 물러갔습니다. 그리고 몇 년 후 돌아와서 그녀의 집과 밭이 낯선 사람의 소유임을 알게 되었습니다. 그 여자가 사마리아 왕에게 상소하여 그들을 감옥에 가두었더니 그녀의 다소 놀라운 태도가 회복되었습니다(왕하 8:1-6을 비교하라).","source_sha256":"6789b1fc4990608074c4e6abb15047cd4b631d35540a6f2a2bc2b66afebfd266","citation_candidates":[{"source":"Josh. 19:18","passage":"jos-19","verse":18,"ref":"jos-19:18","status":"KRV_VERIFIED","exact_korean_token":"수넴"},{"source":"1 Sam. 28:4","passage":"1sa-28","verse":4,"ref":"1sa-28:4","status":"KRV_VERIFIED","exact_korean_token":"수넴"},{"source":"2 Kings 4:8-37","passage":"2ki-4","verse":8,"ref":"2ki-4:8","status":"KRV_VERIFIED","exact_korean_token":"수넴"},{"source":"2 Kings 8:1-6","passage":"2ki-8","verse":1,"ref":"2ki-8:1","status":"KRV_VERIFIED","exact_korean_token":null}],"status":"READER_REFERENCE_ONLY"}];
